TN.defSec("eent-oral",{"periorbital-orbital-cellulitis":{"id":"periorbital-orbital-cellulitis","variants":[{"id":"preseptal-outpatient","o":{"A":[{"t":"Amoxicillin/clavulanate 20 mg/kg/day PO divided every 12 h (adults 500 mg PO three times daily) or a first-generation cephalosporin (cephalexin)"}],"T":[{"t":"Hot packs; confirm visual acuity, pupils and extraocular movements normal"}],"Co":[{"t":"Ophthalmology follow-up within 24–48 h"}]},"name":"Preseptal cellulitis, nontoxic, no eye involvement (outpatient)","level":"III","imp":"Preseptal (periorbital) cellulitis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"کودک ۸ ساله با تورم و قرمزی پلک پس از نیش حشره؛ بینایی و حرکات چشم طبیعی، بدون تب.","why":"آنتی‌بیوتیک خوراکی و پیگیری 24 تا 48 ساعت."},{"id":"orbital-cellulitis-iv","o":{"I":[{"t":"CT orbit (and sinuses) with contrast (or MRI) to evaluate orbital involvement / abscess"}],"L":[{"t":"CBC, blood cultures, CRP / ESR, electrolytes, creatinine"}],"A":[{"t":"Cefuroxime 50 mg/kg IV every 8 h, or ceftriaxone 50 mg/kg IV every 12 h, or ampicillin–sulbactam 50 mg/kg IV every 6 h","fl":[{"k":"hi","v":""}]},{"t":"Add IV vancomycin if MRSA suspected; penicillin-allergic adults: fluoroquinolone PLUS metronidazole or clindamycin"}],"T":[{"t":"Visual acuity, pupils (APD), extraocular movements; neuro checks (cavernous sinus thrombosis / intracranial extension)"}],"Co":[{"t":"Emergent ophthalmology consultation; admit; ENT (sinus source); neurosurgery if intracranial extension"}]},"name":"Postseptal (orbital) cellulitis / severe or high-risk preseptal cellulitis","level":"I","imp":"Orbital cellulitis","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"کودک ۴ ساله با تب، تورم اربیت، پروپتوز و درد با حرکات چشم.","why":"CT اربیت و آنتی‌بیوتیک IV فوری؛ چشم‌پزشکی."}],"ch":"149","name":"Preseptal (periorbital) and postseptal (orbital) cellulitis","name_fa":"سلولیت پره‌سپتال (دور چشم) و پوست‌سپتال (اربیتال)","cc":["eye","fever"],"keywords":"preseptal cellulitis, periorbital cellulitis, orbital cellulitis, postseptal, CT orbit, amoxicillin-clavulanate, cefuroxime, ampicillin-sulbactam, vancomycin, سلولیت دور چشم, سلولیت اربیت","status":"draft","features":["پره‌سپتال: عفونت بافت دور چشم؛ پوست‌سپتال: درگیری اربیت؛ هر دو عمدتاً کودکان < 10 سال؛ اشک‌ریزش زیاد، اریتم، گرمی، حساسیت پلک و بافت دور چشم","پره‌سپتال: بدون درگیری چشم: حدت بینایی، پاسخ مردمک و ظاهر چشم طبیعی و بدون درد با حرکات خارج‌چشمی؛ در صورت هر یک از این یا نگرانی پوست‌سپتال: CT با کنتراست اربیت (یا MRI)"],"ddx":[{"n":"Orbital cellulitis / abscess / cavernous sinus thrombosis |","cm":1},{"n":"Dacryocystitis / hordeolum / allergic periorbital edema |"}],"redflags":["پروپتوز، درد با حرکات چشم، کاهش بینایی، APD، دوبینی، تب بالا، سمیت سیستمیک"],"guide":"پره‌سپتال بدون سمیت: سرپایی با amoxicillin/clavulanate 20 mg/kg PO تقسیم هر 12 ساعت (بزرگسال 500 mg PO سه بار روزانه) یا سفالوسپورین نسل اول، کمپرس گرم و پیگیری چشم‌پزشکی 24 تا 48 ساعت. موارد شدید یا پرخطر (کودک < 5 سال، بیماری همراه مهم) یا هر پوست‌سپتال: مشاوره اورژانس چشم‌پزشکی و بستری برای آنتی‌بیوتیک IV: تجربی: cefuroxime 50 mg/kg IV هر 8 ساعت یا ceftriaxone 50 mg/kg هر 12 ساعت یا ampicillin–sulbactam 50 mg/kg IV هر 6 ساعت؛ vancomycin اگر MRSA مشکوک؛ آلرژی پنی‌سیلین (بزرگسال): فلوروکینولون + metronidazole یا clindamycin.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 149: Eye Emergencies, pp. 813–825"},"stye-chalazion":{"id":"stye-chalazion","variants":[{"id":"stye-chalazion-main","o":{"T":[{"t":"Warm, wet compresses four times daily"},{"t":"Erythromycin 0.5% ophthalmic ointment twice daily for 7–10 days"}],"Co":[{"t":"Ophthalmology referral for persistent or recurrent lesions"}]},"name":"Stye / acute chalazion","level":"III","imp":"Stye (external hordeolum) / chalazion","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۳۰ ساله با برجستگی دردناک و قرمز لبه پلک.","why":"کمپرس گرم و پماد."}],"ch":"149","name":"Stye (external hordeolum) and chalazion","name_fa":"گل‌مژه (hordeolum) و شالازیون","cc":["eye"],"keywords":"stye, hordeolum, chalazion, meibomian gland, warm compress, erythromycin ointment, گل مژه, شالازیون","status":"draft","features":["stye: عفونت حاد غده چربی کنار خط مژه؛ پوستول در لبه پلک؛ chalazion: التهاب حاد یا مزمن پلک ناشی از انسداد غده meibomian در tarsal plate؛ حاد ممکن دردناک؛ مزمن معمولاً بی‌درد"],"ddx":[{"n":"Preseptal cellulitis |","cm":1},{"n":"Sebaceous cell carcinoma (recurrent chalazion) |"}],"redflags":["ضایعه راجعه/مقاوم، گسترش سلولیت"],"guide":"stye یا chalazion حاد: کمپرس گرم و مرطوب 4 بار روزانه و پماد erythromycin 0.5% چشمی دو بار روزانه × 7 تا 10 روز؛ ضایعه پایدار یا راجعه: ارجاع چشم‌پزشک.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 149: Eye Emergencies, pp. 813–825"},"conjunctivitis":{"id":"conjunctivitis","variants":[{"id":"conjunctivitis-bacterial","o":{"T":[{"t":"Fluorescein staining of the cornea (exclude abrasion, ulcer, dendrite); avoid topical anesthetics for home use"}],"A":[{"t":"Erythromycin 0.5% ophthalmic ointment half inch to lower lid 2–4 times daily for 5–7 days; or ciprofloxacin 0.3% solution 1–2 drops every 4 h; or tobramycin 0.3% solution 1–2 drops every 4 h; or sulfacetamide 10% solution 1–2 drops four times daily","fl":[{"k":"ci","v":"avoid gentamicin (ocular irritation); sulfacetamide not for contact lens wearers"}]}],"Co":[{"t":"Ophthalmology follow-up if no improvement; change antibiotic if erythromycin ineffective in children (H. influenzae, M. catarrhalis)"}]},"name":"Bacterial conjunctivitis (non-contact-lens wearer)","level":"III","imp":"Bacterial conjunctivitis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۳۰ ساله با ترشح موکوپورولنت و چسبندگی مژه‌ها صبح؛ بینایی طبیعی و فلورسئین بدون ضایعه.","why":"آنتی‌بیوتیک موضعی 5 تا 7 روز."},{"id":"conjunctivitis-contact-lens","o":{"T":[{"t":"Slit-lamp fluorescein examination; discard contact lens, do not replace until infection completely resolved","fl":[{"k":"ci","v":"no eye patching"}]}],"A":[{"t":"Ciprofloxacin 0.3% solution 1–2 drops every 2 h while awake for 2 days then every 4 h (ointment half inch to lower lid 3 times daily for 2 days); or ofloxacin 0.3% solution; or tobramycin 0.3% solution 1–2 drops every 4 h","fl":[{"k":"ci","v":"do not use erythromycin ointment or sulfacetamide for contact lens wearers"}]}],"Co":[{"t":"Ophthalmology follow-up 24 h"}]},"name":"Conjunctivitis in contact lens wearer (anti-pseudomonal coverage)","level":"II","imp":"Conjunctivitis in contact lens wearer","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۲۵ ساله لنزپوش با قرمزی، ترشح و درد خفیف چشم.","why":"کراتیت/زخم را رد کن و پوشش Pseudomonas."},{"id":"conjunctivitis-viral","o":{"T":[{"t":"Fluorescein staining (exclude dendritic lesions); cool compresses four times daily; artificial tears five or six times daily"},{"t":"Naphazoline/pheniramine 0.025%/0.3% one drop three times daily as needed for congestion / itching","fl":[{"k":"ci","v":"avoid in glaucoma"}]},{"t":"Hand hygiene, transmission precautions (extremely contagious)"}],"A":[{"t":"Topical antibiotics only if viral vs bacterial cannot be distinguished (routine use discouraged)"}],"Co":[{"t":"Ophthalmology follow-up in 7–14 days"}]},"name":"Viral conjunctivitis","level":"III","imp":"Viral conjunctivitis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۳۵ ساله با ترشح آبکی، قرمزی، chemosis و علائم سرماخوردگی و غده پیش‌گوش.","why":"حمایتی و احتیاط انتقال."},{"id":"conjunctivitis-allergic","o":{"T":[{"t":"Eliminate inciting agent; cool compresses four times daily; artificial tears five or six times daily"},{"t":"Naphazoline/pheniramine 0.025%/0.3% one drop four times daily; olopatadine 0.1% one drop twice daily","fl":[{"k":"ci","v":"avoid decongestant in glaucoma"}]},{"t":"Severe: mild topical steroid ONLY in consultation with ophthalmologist"}],"Co":[{"t":"Ophthalmology / allergist follow-up as needed"}]},"name":"Allergic conjunctivitis","level":"III","imp":"Allergic conjunctivitis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۲۰ ساله با خارش شدید دو چشم، اشک‌ریزش و chemosis در بهار.","why":"حذف آلرژن و آنتی‌هیستامین موضعی."},{"id":"conjunctivitis-hyperacute-gonococcal","o":{"L":[{"t":"Gram stain (gram-negative intracellular diplococci) and culture; neonatal: sepsis workup (consider chlamydia / HSV)"}],"A":[{"t":"Parenteral ceftriaxone for N. gonorrhoeae (dose per local protocol)","fl":[{"k":"hi","v":""}]}],"T":[{"t":"Saline irrigation to remove discharge; slit-lamp examination for corneal involvement"}],"Co":[{"t":"Emergent ophthalmology; neonate: inpatient workup for disseminated disease (gonorrhea); if chlamydia suspected rule out associated pneumonia before discharge"}]},"name":"Hyperacute purulent conjunctivitis (gonococcal) / neonatal conjunctivitis","level":"I","imp":"Hyperacute purulent conjunctivitis, suspected gonococcal","cond":"Emergent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۲۲ ساله با ترشح چرکی فراوان از دیروز و تورم پلک؛ یا نوزاد 5 روزه با ترشح چرکی.","why":"Gram و کشت، ceftriaxone و مشاوره اورژانس."}],"ch":"149","name":"Conjunctivitis (bacterial, viral, allergic, hyperacute gonococcal)","name_fa":"ورم ملتحمه (باکتریال، ویروسی، آلرژیک، گونوکوکی)","cc":["eye"],"keywords":"conjunctivitis, pink eye, bacterial conjunctivitis, viral conjunctivitis, allergic conjunctivitis, gonococcal conjunctivitis, contact lens, fluorescein, ملتحمه, قرمزی چشم","status":"draft","features":["باکتریال: چسبندگی مژه‌ها، ترشح موکوپورولنت خفیف تا متوسط و التهاب ملتحمه؛ فلورسئین برای رد سایش، زخم و ضایعه دندریتیک؛ H. influenzae و M. catarrhalis در کودک؛ لنزپوش: پوشش Pseudomonas","ترشح چرکی شدید با شروع فوق‌حاد (12 تا 24 ساعت): شک گونوکوک: مشاوره اورژانس چشم‌پزشکی؛ Gram: دیپلوکوک گرم‌منفی داخل‌سلولی؛ نوزاد: شک STD (gonorrhea: ورک‌آپ بستری برای انتشار؛ chlamydia: رد پنومونی؛ HSV)","ویروسی: ترشح آبکی، chemosis، التهاب ملتحمه؛ اغلب با علائم تنفسی ویروسی و گاه لنفادنوپاتی پیش‌گوش؛ فلورسئین برای دندریت؛ بسیار مسری","آلرژیک: خارش، ترشح آبکی، chemosis با سابقه آلرژی؛ بدون ضایعه با فلورسئین و بدون گره پیش‌گوش؛ پاپیل ملتحمه در slit lamp"],"ddx":[{"n":"Corneal abrasion / ulcer / HSV keratitis |","cm":1},{"n":"Acute angle-closure glaucoma / iritis |","cm":1},{"n":"Gonococcal / chlamydial conjunctivitis |"}],"redflags":["ترشح چرکی فوق‌حاد، کاهش بینایی، درد شدید، فوتوفوبیا، لنزپوش، نوزاد"],"guide":"باکتریال: آنتی‌بیوتیک موضعی 5 تا 7 روز (جدول 149-1): erythromycin ointment نیم‌اینچ پایین پلک 2 تا 4 بار؛ ciprofloxacin 0.3% قطره 1 تا 2 قطره هر 4 ساعت (یا ointment 2 تا 3 بار)؛ ofloxacin؛ tobramycin؛ sulfacetamide 10% (نه در لنزپوش)؛ کینولون برای کودک (جذب سیستمیک کم)؛ از gentamicin به‌علت تحریک پرهیز؛ لنزپوش: پوشش آنتی‌سودوموناس و دور انداختن لنز. گونوکوک: کشت، ceftriaxone تزریقی و شستشوی سالین. ویروسی: کمپرس سرد 4 بار روزانه، naphazoline/pheniramine 0.025%/0.3% یک قطره 3 بار روزانه در صورت نیاز، اشک مصنوعی 5 تا 6 بار روزانه، پیگیری 7 تا 14 روز؛ آنتی‌بیوتیک روتین توصیه نمی‌شود مگر افتراق ممکن نباشد؛ احتیاط انتقال. آلرژیک: حذف عامل، کمپرس سرد، اشک مصنوعی 5 تا 6 بار، naphazoline/pheniramine 4 بار روزانه (یا olopatadine 0.1% دو بار)؛ موارد شدید استروئید ملایم فقط با مشاوره چشم‌پزشک.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 149: Eye Emergencies, pp. 813–825"},"ocular-herpes-simplex":{"id":"ocular-herpes-simplex","variants":[{"id":"hsv-eye-main","o":{"T":[{"t":"Slit-lamp fluorescein examination; check corneal sensation"},{"t":"Erythromycin 0.5% ophthalmic ointment twice daily; warm soaks three times daily to skin lesions","fl":[{"k":"ci","v":"topical steroids strictly contraindicated in HSV"}]}],"A":[{"t":"Eyelids only: acyclovir 800 mg PO five times daily for 7–10 days"},{"t":"Conjunctival involvement: trifluorothymidine (trifluridine) 1% drops nine times daily"},{"t":"Corneal / deeper involvement: antiviral per consulting ophthalmologist"}],"Co":[{"t":"Ophthalmology consultation; close follow-up from ED"}]},"name":"Ocular HSV (eyelid / conjunctival / corneal dendrite)","level":"II","imp":"Herpes simplex ocular infection","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۳۵ ساله با قرمزی، فوتوفوبیا و درد چشم؛ slit lamp: دندریت قرنیه.","why":"ضدویروس و مشاوره چشم؛ بدون استروئید."},{"id":"hsv-neonatal-eye","o":{"L":[{"t":"Sepsis workup (CBC, blood / urine / CSF cultures, HSV PCR from conjunctiva / skin / blood / CSF, liver enzymes)"}],"A":[{"t":"Acyclovir 20 mg/kg IV every 8 h","fl":[{"k":"hi","v":""}]},{"t":"Topical antivirals (1% trifluridine, 0.1% iododeoxyuridine, or 3% vidarabine)"}],"T":[{"t":"Bedside emergent ophthalmology; no steroid drops"}],"Co":[{"t":"Emergent ophthalmology; neonatology / infectious disease; admit"}]},"name":"Neonatal conjunctivitis with suspected HSV","level":"I","imp":"Neonatal HSV conjunctivitis","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"نوزاد 8 روزه با ورم ملتحمه و وزیکول پوستی.","why":"acyclovir IV و ورک‌آپ سپسیس."}],"ch":"149","name":"Herpes simplex virus ocular infection (eyelid, conjunctiva, cornea)","name_fa":"عفونت چشمی هرپس سیمپلکس (HSV)","cc":["eye"],"keywords":"herpes simplex keratitis, dendritic ulcer, HSV conjunctivitis, trifluridine, acyclovir, neonatal HSV, آبله هرپس چشم, کراتیت دندریتیک","status":"draft","features":["درگیری پلک، ملتحمه یا قرنیه؛ ضایعه قرنیه با فلورسئین روشن رنگ می‌گیرد: «dendrite» (نقص اپیتلیال خطی منشعب با انتهای bulb) یا «geographic ulcer»؛ حس قرنیه ممکن کم؛ تظاهر متغیر و ظریف؛ نباید با ورم ملتحمه اشتباه شود ← معاینه slit lamp با فلورسئین","نوزاد: ورم ملتحمه به‌ویژه با ضایعات مخاطی-پوستی، حتی بدون عفونت مادر"],"ddx":[{"n":"Herpes zoster ophthalmicus / bacterial keratitis / corneal ulcer |","cm":1},{"n":"Conjunctivitis (viral / bacterial) |"}],"redflags":["ضایعه قرنیه، نوزاد، سرکوب ایمنی"],"guide":"شک HSV: مشاوره چشم‌پزشکی. فقط پلک: acyclovir 800 mg PO پنج بار روزانه × 7 تا 10 روز. ملتحمه: trifluorothymidine 1% قطره 9 بار روزانه؛ erythromycin 0.5% ointment دو بار و کمپرس گرم 3 بار روزانه برای جلوگیری از عفونت ثانویه باکتریال. درگیری قرنیه یا عمیق‌تر: انتخاب دارو با چشم‌پزشک. استروئید موضعی در همه موارد HSV کاملاً ممنوع. پیگیری نزدیک. نوزاد: acyclovir 20 mg/kg IV هر 8 ساعت + ضدویروس موضعی (trifluridine 1%، iododeoxyuridine 0.1% یا vidarabine 3%)؛ ورک‌آپ سپسیس؛ مشاوره اورژانس بالین؛ بدون استروئید.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 149: Eye Emergencies, pp. 813–825"},"herpes-zoster-ophthalmicus":{"id":"herpes-zoster-ophthalmicus","variants":[{"id":"hzo-main","o":{"T":[{"t":"Slit-lamp examination with fluorescein; IOP; erythromycin 2% ointment + warm compresses to skin lesions; erythromycin 0.5% ophthalmic ointment to eye twice daily"},{"t":"Cyclopentolate 1% one drop three times daily; cool compresses; oral opioid analgesia"},{"t":"If iritis and NO corneal lesion: prednisolone acetate 1% one drop every 1–6 h (ophthalmology guidance)","fl":[{"k":"ci","v":"no steroids if corneal lesions / HSV keratitis"}]}],"A":[{"t":"Acyclovir 800 mg PO five times daily, or famciclovir 500 mg PO three times daily, or valacyclovir 1000 mg PO three times daily for 7–10 days (if skin lesions < 7 days)","fl":[{"k":"ci","v":"dose adjust in renal impairment"}]}],"Co":[{"t":"Ophthalmology consultation (all HZO); admit with IV acyclovir in severe cases; outpatient evaluation for immunocompromise if age < 40"}]},"name":"Herpes zoster ophthalmicus","level":"II","imp":"Herpes zoster ophthalmicus","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۶۵ ساله با زونا پیشانی و نوک بینی، قرمزی و درد چشم و فوتوفوبیا.","why":"ضدویروس خوراکی؛ مشاوره چشم؛ مراقب استروئید."}],"ch":"149","name":"Herpes zoster ophthalmicus (HZO)","name_fa":"هرپس زوستر چشمی (HZO)","cc":["eye","rash"],"keywords":"herpes zoster ophthalmicus, Hutchinson sign, shingles eye, pseudodendrite, valacyclovir, zoster eye, زونا چشم","status":"draft","features":["زونا در توزیع تری‌ژمینال با درگیری چشم؛ علامت Hutchinson (نوک بینی) = HZO بالقوه؛ فوتوفوبیا و درد از iritis؛ slit lamp: «pseudodendrite» (پلاک موکوسی با رنگ‌گیری ضعیف)","زیر 40 سال با HZO: ارزیابی سرپایی برای نقص ایمنی"],"ddx":[{"n":"HSV keratitis |","cm":1},{"n":"Iritis / glaucoma |"}],"redflags":["علامت Hutchinson، ضایعه قرنیه، کاهش بینایی، نقص ایمنی"],"guide":"اگر ضایعات پوستی < 7 روز: acyclovir 800 mg PO پنج بار روزانه یا famciclovir 500 mg سه بار روزانه یا valacyclovir 1000 mg سه بار روزانه × 7 تا 10 روز. روی ضایعات پوستی erythromycin 2% ointment و کمپرس گرم؛ درگیری چشم: erythromycin 0.5% ointment چشمی دو بار روزانه. راحتی: اوپیوئید خوراکی، cyclopentolate 1% یک قطره 3 بار روزانه و کمپرس سرد. iritis: prednisolone acetate 1% یک قطره هر 1 تا 6 ساعت ولی فقط اگر ضایعه قرنیه در slit lamp نباشد (استروئید موضعی در HSV کراتوکونژونکتیویت فاجعه‌بار). موارد شدید: بستری و acyclovir IV. مشاوره چشم‌پزشکی در همه.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 149: Eye Emergencies, pp. 813–825"},"corneal-ulcer":{"id":"corneal-ulcer","variants":[{"id":"corneal-ulcer-main","o":{"L":[{"t":"Corneal culture / scraping before antibiotics (ophthalmology); Gram stain"}],"A":[{"t":"Ofloxacin 0.3% or ciprofloxacin 0.3% ophthalmic solution: 1 drop every hour in affected eye (per ophthalmology regimen)","fl":[{"k":"hi","v":""}]},{"t":"Antifungal / antiviral agents for immunocompromised only in consultation with ophthalmologist"}],"T":[{"t":"Cyclopentolate 1% one drop three times daily for pain; analgesia; discard contact lenses","fl":[{"k":"ci","v":"eye patching strictly contraindicated; avoid steroid drops unless advised by ophthalmologist"}]}],"Co":[{"t":"Ophthalmology: ideally seen in ED for culture before antibiotics; otherwise within 12–24 h"}]},"name":"Corneal ulcer","level":"I","imp":"Corneal ulcer (infectious keratitis)","cond":"Emergent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۲۸ ساله لنزپوش با درد شدید، قرمزی، فوتوفوبیا و لکه سفید روی قرنیه؛ hypopyon کوچک.","why":"کشت و فلوروکینولون هر ساعت؛ بدون patch."}],"ch":"149","name":"Corneal ulcer (infectious keratitis)","name_fa":"زخم قرنیه (کراتیت عفونی)","cc":["eye"],"keywords":"corneal ulcer, infectious keratitis, Pseudomonas, contact lens, hypopyon, ofloxacin, ciprofloxacin, زخم قرنیه","status":"draft","features":["عفونت جدی استرومای قرنیه: باکتری (Pseudomonas aeruginosa)، ویروس (HSV، VZV) و قارچ؛ نقص ایمنی: قارچی/ویروسی؛ ارتباط با تروما، لنز extended-wear و خواب با لنز؛ درد، قرمزی، اشک‌ریزش، فوتوفوبیا و تاری دید","slit lamp: نقص رنگ‌گیر قرنیه با ارتشاح سفید مه‌آلود اطراف، iritis و گاه hypopyon"],"ddx":[{"n":"HSV keratitis / HZO |","cm":1},{"n":"Corneal abrasion / foreign body / iritis |"}],"redflags":["hypopyon، لنزپوش، نقص ایمنی، کاهش بینایی"],"guide":"ofloxacin 0.3% یا ciprofloxacin 0.3% قطره، یک قطره در چشم مبتلا هر ساعت (شدید: هر 30 دقیقه در جدول 149-1: 1 تا 2 قطره هر 30 دقیقه بیدار + هر 4 تا 6 ساعت پس از خواب 2 روز، سپس هر ساعت 5 تا 7 روز). ضدقارچ/ضدویروس در نقص ایمنی با مشورت چشم‌پزشک. cycloplegic (cyclopentolate 1% یک قطره 3 بار روزانه) برای درد. patch چشم اکیداً ممنوع (تشدید عفونت Pseudomonas). قطره استروئید مگر با توصیه چشم‌پزشک. ایده‌آل: معاینه چشم‌پزشک در ED و کشت زخم قبل از آنتی‌بیوتیک؛ در غیر این صورت ظرف 12 تا 24 ساعت.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 149: Eye Emergencies, pp. 813–825"},"iritis-anterior-uveitis":{"id":"iritis-anterior-uveitis","variants":[{"id":"iritis-main","o":{"L":[{"t":"IOP; fluorescein exam (abrasion / ulcer / dendrite); systemic etiology workup as indicated (CBC, ESR / CRP, HLA-B27, syphilis, TB / sarcoid screen)"}],"S":[{"t":"Tropicamide 1% 1–2 drops (or cyclopentolate 1% one drop three times daily; homatropine 2% twice daily for iritis)","fl":[{"k":"ci","v":"mydriatics avoid in glaucoma"}]},{"t":"Prednisolone acetate 1% ONLY if directed by ophthalmologist","fl":[{"k":"ci","v":"not if corneal lesion / HSV"}]}],"T":[{"t":"Dark glasses; oral analgesia"}],"Co":[{"t":"Ophthalmology consultation with follow-up in 24–48 h"}]},"name":"Iritis","level":"III","imp":"Iritis (anterior uveitis)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۳۵ ساله با قرمزی یک‌چشمی، فوتوفوبیا و درد همدلانه؛ slit lamp: سلول و flare.","why":"سیکلوپلژیک و چشم‌پزشکی؛ ورک‌آپ سیستمیک."}],"ch":"149","name":"Iritis (anterior uveitis)","name_fa":"ایریت (یووئیت قدامی)","cc":["eye"],"keywords":"iritis, anterior uveitis, consensual photophobia, hypopyon, cyclopentolate, tropicamide, prednisolone, ایریت","status":"draft","features":["التهاب مجرای یووئال قدامی (عنبیه و جسم مژگانی)؛ علل (جدول 149-2): سیستمیک (JRA، اسپوندیلیت آنکیلوزان، کولیت اولسراتیو، Reiter، Behçet، سارکوئیدوز)، عفونی (TB، Lyme، توکسوپلاسموز، سیفلیس، HSV، VZV، آدنوویروس)، بدخیمی (لوسمی، لنفوم، ملانوم)، تروما/محیطی (جسم خارجی قرنیه، بلانت، UV)","قرمزی چشم، فوتوفوبیا، کاهش بینایی؛ علامت مشخصه: درد تونیک/همدلانه (درد چشم مبتلا با نور به چشم سالم)؛ slit lamp: WBC و flare در اتاق قدامی؛ hypopyon؛ فلورسئین برای سایش/زخم/دندریت؛ اندازه‌گیری IOP (ممکن بالا)"],"ddx":[{"n":"Acute angle-closure glaucoma / corneal ulcer / HSV |","cm":1},{"n":"Conjunctivitis / scleritis / endophthalmitis |"}],"redflags":["hypopyon، IOP بالا، کاهش بینایی، تروما نافذ"],"guide":"پس از تشخیص: ورک‌آپ ED برای علت سیستمیک و درمان؛ درمان علامتی با tropicamide (جدول 149-1)؛ cycloplegic (cyclopentolate 1%)؛ مشاوره چشم‌پزشکی و پیگیری 24 تا 48 ساعت؛ قطره استروئید (prednisolone acetate 1%) فقط با دستور چشم‌پزشک.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 149: Eye Emergencies, pp. 813–825"},"endophthalmitis":{"id":"endophthalmitis","variants":[{"id":"endophthalmitis-main","o":{"I":[{"t":"Ocular ultrasonography / CT orbit if trauma / foreign body suspected"}],"L":[{"t":"Vitreous / aqueous cultures (ophthalmology); blood cultures if hematogenous spread suspected; CBC"}],"A":[{"t":"Intravitreal and systemic broad-spectrum antibiotics per ophthalmology (vancomycin + ceftazidime typical)","fl":[{"k":"note","v":"vitreous aspiration / vitrectomy and steroids per ophthalmology"}]}],"T":[{"t":"Eye shield; NPO if surgery; analgesia"}],"Co":[{"t":"Emergency ophthalmology consultation; admit"}]},"name":"Endophthalmitis","level":"I","imp":"Endophthalmitis","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مرد ۶۸ ساله 3 روز پس از جراحی آب مروارید با درد شدید، کاهش بینایی و hypopyon.","why":"مشاوره فوری چشم و آنتی‌بیوتیک داخل‌چشمی."}],"ch":"149","name":"Endophthalmitis","name_fa":"اندوفتالمیت","cc":["eye"],"keywords":"endophthalmitis, intraocular infection, post cataract surgery, vitrectomy, اندوفتالمیت","status":"draft","features":["عفونت ساختارهای عمیق کره چشم؛ درد و کاهش بینایی؛ اغلب عارضه نفوذ کره (تروما یا جراحی چشم)؛ ممکن انتشار هماتوژن؛ عوامل: Staphylococcus، Streptococcus، Haemophilus، Bacillus"],"ddx":[{"n":"Iritis / ruptured globe / retinal detachment |","cm":1}],"redflags":["درد و کاهش بینایی پس از جراحی/تروما، hypopyon"],"guide":"مشاوره اورژانس چشم‌پزشکی و بستری؛ درمان: آسپیراسیون ویتره، ویترکتومی، آنتی‌بیوتیک داخل‌چشمی و سیستمیک و استروئید.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 149: Eye Emergencies, pp. 813–825"},"corneal-abrasion-foreign-body":{"id":"corneal-abrasion-foreign-body","variants":[{"id":"corneal-abrasion-simple","o":{"L":[{"t":"(none) — visual acuity before treatment; fluorescein exam with cobalt blue light; lid eversion for foreign body"}],"S":[{"t":"Proparacaine 0.5% 1–2 drops for examination / foreign body removal only","fl":[{"k":"ci","v":"NEVER prescribe topical anesthetics for home use"}]},{"t":"Ketorolac ophthalmic solution one drop four times daily for pain","fl":[{"k":"ci","v":"avoid in NSAID allergy"}]},{"t":"Severe pain / large abrasion: opioid analgesia and / or cyclopentolate 1% one drop three times daily"}],"A":[{"t":"Erythromycin ophthalmic ointment half inch to lower lid two to four times daily"}],"T":[{"t":"Corneal foreign body removal under slit lamp with 25-gauge needle, eye spud or burr (proparacaine; sober cooperative patient); rust ring removal now or in 24–48 h; deep / central visual axis foreign body → ophthalmologist"},{"t":"No eye patching needed (does not hasten healing)"}],"Co":[{"t":"Ophthalmology re-examination in 24–48 h (sooner if large or involving visual axis; all foreign bodies referral within 24 h); update tetanus if needed"}]},"name":"Simple corneal abrasion / corneal foreign body (non-contact-lens)","level":"III","imp":"Corneal abrasion / corneal foreign body","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۳۰ ساله با درد شدید و اشک‌ریزش چشم پس از خراش با شاخه درخت؛ فلورسئین: سایش 3 mm.","why":"ketorolac قطره و پماد آنتی‌بیوتیک؛ بدون patch."},{"id":"corneal-abrasion-contact-lens-uv","o":{"S":[{"t":"Ketorolac ophthalmic solution one drop four times daily; cyclopentolate 1% one drop three times daily; opioid analgesia (UV keratitis often needs more aggressive pain control)"}],"A":[{"t":"Contact lens wearer: ciprofloxacin, ofloxacin, or tobramycin ophthalmic (antipseudomonal)","fl":[{"k":"ci","v":"no erythromycin only; no patching"}]}],"T":[{"t":"Discard contact lens; avoid further UV exposure; healing typically 2–3 days"}],"Co":[{"t":"Ophthalmology follow-up 24–48 h"}]},"name":"Abrasion in contact lens wearer / ultraviolet (arc-welder) keratitis","level":"II","imp":"Corneal abrasion, contact lens wearer / ultraviolet keratitis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"جوشکار ۳۵ ساله بدون محافظ با درد شدید و فوتوفوبیا دو چشم 8 ساعت پس از جوشکاری؛ یا لنزپوش با سایش قرنیه.","why":"آنتی‌بیوتیک ضد pseudomonas در لنزپوش؛ ضددرد قوی در UV."}],"ch":"149","name":"Corneal abrasion, ultraviolet keratitis and corneal foreign body","name_fa":"سایش قرنیه، کراتیت UV و جسم خارجی قرنیه","cc":["eye","wound-bite"],"keywords":"corneal abrasion, welder keratitis, ultraviolet keratitis, corneal foreign body, rust ring, fluorescein, proparacaine, ketorolac ophthalmic, سایش قرنیه, جسم خارجی قرنیه","status":"draft","features":["سایش تروماتیک: نقص اپیتلیال سطحی یا عمیق: اشک‌ریزش، فوتوفوبیا، blepharospasm و درد؛ با فلورسئین و نور cobalt blue سبز می‌درخشد؛ جستجوی جسم خارجی (از جمله ورتکس پلک بالا) به‌ویژه در سایش‌های متعدد و خطی","کراتیت UV («arc welder's»): جوشکاری، سولاریوم، آفتاب طولانی (انعکاس برف/یخ ارتفاع)؛ سوختگی منتشر قرنیه با سایش نقطه‌ای و ادم؛ درد شدید و فوتوفوبیا 6 تا 12 ساعت بعد؛ بهبود 2 تا 3 روز","جسم خارجی قرنیه: سطحی با slit lamp و سوزن 25G، eye spud یا burr؛ rust ring فلزی؛ هایفما (gross یا micro) = شک پارگی کره (نافذ)"],"ddx":[{"n":"Penetrating trauma / ruptured globe (Seidel test) |","cm":1},{"n":"Corneal ulcer / HSV keratitis |","cm":1},{"n":"Iritis / retained foreign body under lid |"}],"redflags":["Seidel مثبت، تاری دید، IOP، hypopyon، لنزپوش با زخم، جسم خارجی عمیق یا مرکزی"],"guide":"بی‌حسی موضعی معاینه: proparacaine 0.5% ترجیحی بر tetracaine (درد کمتر، بی‌حسی مشابه)، 1 تا 2 قطره (شروع 20 ثانیه، مدت 15 دقیقه). سایش ساده: ketorolac قطره چشمی یک قطره 4 بار روزانه برای درد؛ درد شدید و سایش بزرگ: اوپیوئید و/یا cycloplegic (cyclopentolate 1% یک قطره 3 بار روزانه). آنتی‌بیوتیک موضعی: بیشتر erythromycin ointment؛ لنزپوش: ضد pseudomonas (ciprofloxacin، ofloxacin، tobramycin). patching لازم نیست و بهبود را سریع نمی‌کند و در ضایعات مستعد عفونت (لنز، زخم) مضر؛ تجویز بی‌حس‌کننده موضعی برای بیمار مطلقاً ممنوع (آسیب فاجعه‌بار قرنیه). معاینه مجدد 24 تا 48 ساعت توسط چشم‌پزشک (بزرگ یا محور بینایی سریع‌تر). جسم خارجی: با بی‌حسی proparacaine 0.5% (و چشم سالم برای کاهش پلک‌زدن) در بیمار هوشیار همکار؛ عمیق یا محور بینایی: چشم‌پزشک؛ rust ring را فوراً با burr یا 24 تا 48 ساعت بعد؛ پس از برداشتن مثل سایش (cycloplegic، آنتی‌بیوتیک)؛ ارجاع ≤ 24 ساعت.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 149: Eye Emergencies, pp. 813–825"},"eyelid-laceration-blunt-eye-trauma":{"id":"eyelid-laceration-blunt-eye-trauma","variants":[{"id":"eyelid-laceration","o":{"I":[{"t":"CT orbit if full-thickness laceration / suspected globe injury or foreign body"}],"L":[{"t":"Fluorescein instilled into tear layer to check lacrimal / canalicular injury (medial laceration)"}],"A":[{"t":"If ophthalmologist not immediately available and no sight-threatening lesion: cephalexin 500 mg PO four times daily"}],"T":[{"t":"Superficial lacerations: EP repair; lid margin > 1 mm, within 6–8 mm of medial canthus, lacrimal duct / sac, inner lid surface, ptosis, tarsal plate or levator → oculoplastic / ophthalmology repair (operating room for through-and-through, levator, nasolacrimal)"},{"t":"Erythromycin 2% ointment four times daily; gentle cold compresses; tetanus update"}],"Co":[{"t":"Ophthalmology / oculoplastic referral (within 24 h if not immediate)"}]},"name":"Eyelid laceration","level":"II","imp":"Eyelid laceration","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۲۸ ساله با لاسراسیون پلک بالا شامل لبه پلک پس از ضربه.","why":"تعیین نیاز به اکولوپلاستیک و رد پارگی کره."},{"id":"blunt-eye-trauma","o":{"I":[{"t":"CT orbit (ED test of choice; sensitivity as low as 70% for occult globe injury); ocular ultrasonography with minimal pressure only if globe rupture excluded"}],"L":[{"t":"(visual acuity, IOP if globe intact, slit lamp)"}],"S":[{"t":"Antiemetic (ondansetron 4 mg IV) to avoid vomiting-induced IOP rise if globe injury suspected; analgesia"}],"T":[{"t":"Eye shield (no pressure on globe); NPO and head up if ruptured globe suspected; avoid manipulation"},{"t":"Traumatic iritis without corneal injury: prednisolone acetate 1% one drop every 6 h and cyclopentolate 1% one drop every 8 h"},{"t":"Retrobulbar hemorrhage / orbital compartment syndrome (pain, proptosis, impaired EOM, decreased vision, APD, elevated IOP): lateral canthotomy"}],"Co":[{"t":"Ophthalmology (discuss all cases; follow-up within 48 h even if no significant injuries); update tetanus"}]},"name":"Blunt eye trauma (globe rupture to exclude; retrobulbar hemorrhage; traumatic iritis)","level":"I","imp":"Blunt eye trauma","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"مرد ۳۰ ساله با ضربه مشت به چشم، درد، تاری دید و ادم پلک؛ بدون پروپتوز.","why":"پارگی کره را رد، شیلد و CT اربیت؛ چشم‌پزشک."}],"ch":"149","name":"Eyelid laceration and blunt eye trauma (including retrobulbar hemorrhage and traumatic iritis)","name_fa":"لاسراسیون پلک و تروما بلانت چشم","cc":["eye","head-injury","wound-bite"],"keywords":"lid laceration, canalicular injury, blunt eye trauma, retrobulbar hemorrhage, orbital compartment syndrome, lateral canthotomy, traumatic iritis, lens dislocation, لاسراسیون پلک, ضربه چشم, کانتوتومی","status":"draft","features":["لاسراسیون پلک: کوچک سطحی توسط EP؛ نیاز به جراح اکولوپلاستیک: درگیری لبه پلک، < 6 تا 8 mm از کانتوس داخلی یا مجرای/کیسه اشکی، سطح داخلی پلک، پتوز، tarsal plate یا levator؛ لبه پلک > 1 mm نیاز به بستن توسط چشم‌پزشک و < 1 mm می‌تواند خودبه‌خود بهبود یابد؛ آسیب مجرای نازولاکریمال (فلورسئین در لاسراسیون مجاور تأیید می‌کند)؛ لاسراسیون ضخامت‌کامل یا levator یا مجرای اشکی در اتاق عمل؛ همه ضخامت‌کامل: رد لاسراسیون قرنیه و پارگی کره","بلانت: اسپکولوم چشم (یا دو گیره کاغذ خم‌شده) بدون فشار بر کره؛ یکپارچگی کره و حدت بینایی؛ نشانه‌های قرمز: عمق اتاق قدامی غیرطبیعی، مردمک نامنظم یا نابینایی = پارگی کره تا اثبات خلاف؛ شیلد چشم فوراً؛ بدون نشانه سخت: معاینه کامل شامل slit lamp (blowout، سایش، لاسراسیون، جسم خارجی، هایفما، آسیب مردمک، iritis، دررفتگی عدسی)","خونریزی پشت سپتوم (به‌ویژه ضدانعقاد): درد، پروپتوز، اختلال حرکات خارج‌چشمی، کاهش بینایی، APD و IOP بالا؛ سندرم کمپارتمان اربیت: ممکن lateral canthotomy؛ CT اربیت (حساسیت تا 70% برای آسیب پنهان کره)؛ iritis تروماتیک بدون آسیب قرنیه: prednisolone acetate 1% هر 6 ساعت + cyclopentolate 1% هر 8 ساعت"],"ddx":[{"n":"Ruptured globe / orbital compartment syndrome |","cm":1},{"n":"Hyphema / blowout fracture / lens dislocation / retinal detachment |"}],"redflags":["عمق اتاق قدامی غیرطبیعی، مردمک اشک‌قطره‌ای، نابینایی، پروپتوز، APD، IOP بالا"],"guide":"اگر چشم‌پزشک بلافاصله در دسترس نیست برای لاسراسیون پلک پرخطر (و ضایعات تهدیدکننده بینایی رد شده): cephalexin 500 mg PO چهار بار روزانه، erythromycin 2% ointment چهار بار روزانه، کمپرس سرد ملایم و ارجاع ظرف 24 ساعت. بلانت: مشاوره با چشم‌پزشک و پیگیری 48 ساعت حتی بدون آسیب اولیه مهم.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 149: Eye Emergencies, pp. 813–825"},"hyphema":{"id":"hyphema","variants":[{"id":"hyphema-main","o":{"I":[{"t":"CT orbit if rupture suspected (exclude ruptured globe first)"}],"L":[{"t":"IOP (after ruptured globe excluded); sickle cell screen in at-risk patients; coagulation if coagulopathy"}],"S":[{"t":"Antiemetic and analgesia (avoid NSAIDs / aspirin)"}],"T":[{"t":"Head of bed 30–45° (or fully upright); protective eye shield (except during examination and medication)"}],"Co":[{"t":"Emergent ophthalmology evaluation; disposition by ophthalmologist at bedside (30% rebleed risk at 3–5 days)"}]},"name":"Hyphema","level":"I","imp":"Hyphema","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"مرد ۲۵ ساله پس از ضربه توپ به چشم با تاری دید و خون در اتاق قدامی.","why":"سر بالا، شیلد و تصمیم چشم‌پزشک."}],"ch":"149","name":"Hyphema","name_fa":"هایفما","cc":["eye"],"keywords":"hyphema, blood anterior chamber, rebleed, sickle cell, head elevation, eye shield, هایفما","status":"draft","features":["خون در اتاق قدامی؛ اغلب علامت تروما مهم؛ خودبه‌خود در سلول داسی و کوآگولوپاتی؛ افزایش تهدیدکننده بینایی IOP؛ 30% خطر خونریزی مجدد روز 3 تا 5 و نیاز احتمالی به جراحی"],"ddx":[{"n":"Ruptured globe |","cm":1},{"n":"Iritis / glaucoma |"}],"redflags":["IOP بالا، تروما نافذ، سلول داسی"],"guide":"مشاوره اورژانس چشم‌پزشکی در همه. بیمار کاملاً نشسته یا سر بالا 30 تا 45 درجه تا خون پایین بنشیند (بینایی سریع‌تر و ارزیابی اندازه و قطب خلفی)؛ شیلد محافظ جز حین معاینه و دارو؛ پس از رد پارگی کره: ارزیابی سایر آسیب‌های چشمی. تصمیم ترخیص با چشم‌پزشک بر بالین بدون توجه به اندازه.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 149: Eye Emergencies, pp. 813–825"},"orbital-blowout-fracture-ruptured-globe":{"id":"orbital-blowout-fracture-ruptured-globe","variants":[{"id":"orbital-blowout","o":{"I":[{"t":"CT orbit with 1.5-mm cuts (additional studies as indicated)"}],"A":[{"t":"Cephalexin 250–500 mg PO four times daily for 10 days (prophylaxis, sinus involvement)"}],"T":[{"t":"Advise no nose blowing; exclude associated ocular injury (33%): slit lamp, IOP, fundus; analgesia"}],"Co":[{"t":"Ophthalmology referral for formal dilated exam (all isolated blowout fractures, with or without entrapment); ENT / plastic surgery for entrapment"}]},"name":"Orbital blowout fracture","level":"II","imp":"Orbital blowout fracture","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۲۵ ساله پس از مشت به چشم با دوبینی هنگام نگاه به بالا، بی‌حسی گونه و آمفیزم زیرجلدی.","why":"CT اربیت و آنتی‌بیوتیک؛ چشم‌پزشک."},{"id":"ruptured-globe","o":{"I":[{"t":"CT orbit (foreign body / ruptured globe; low sensitivity for occult injury — do not rely on it to exclude)"}],"S":[{"t":"Broad-spectrum antibiotics (IV)","fl":[{"k":"hi","v":""}]},{"t":"Antiemetic (ondansetron 4 mg IV) to prevent increased IOP from vomiting; analgesia"}],"T":[{"t":"Protective eye shield immediately; upright position; NPO; NO further manipulation or examination, no pressure on globe; update tetanus"}],"Co":[{"t":"Emergent ophthalmology call immediately (surgical exploration / repair)"}]},"name":"Penetrating ocular trauma / suspected ruptured globe","level":"I","imp":"Penetrating eye trauma / ruptured globe","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"کارگر ۳۵ ساله حین چکش‌کاری بدون عینک با درد، کاهش بینایی، مردمک اشک‌قطره‌ای و Seidel مثبت.","why":"شیلد، NPO، آنتی‌بیوتیک، ضداستفراغ و چشم‌پزشک فوری."}],"ch":"149","name":"Orbital blowout fracture and penetrating trauma / ruptured globe","name_fa":"شکستگی blowout اربیت و تروما نافذ / پارگی کره چشم","cc":["eye","head-injury","trauma-major"],"keywords":"orbital blowout fracture, inferior rectus entrapment, ruptured globe, open globe, Seidel test, intraocular foreign body, teardrop pupil, شکستگی کف اربیت, پارگی کره","status":"draft","features":["blowout: دیواره تحتانی و داخلی؛ گیرافتادن راست تحتانی ← محدودیت حرکت و دوبینی هنگام نگاه به بالا؛ پارستزی توزیع عصب infraorbital، آمفیزم زیرجلدی (با عطسه/فین کردن)؛ 33% آسیب چشمی همراه","پارگی/نفوذ کره: فاجعه؛ شواهد: subconjunctival hemorrhage شدید، اتاق قدامی کم‌عمق یا عمیق نسبت به چشم دیگر، هایفما، مردمک اشک‌قطره‌ای، محدودیت حرکات، خروج محتوای کره، کاهش قابل‌توجه بینایی؛ جسم خارجی کوچک ممکن معاینه تقریباً نرمال (کوبیدن/سنگ‌زنی بدون محافظ)؛ Seidel test (جریان سبز روشن فلورسئین) پاتوگنومونیک ولی ممکن در زخم بسته‌شده منفی؛ وجود سایش آن را رد نمی‌کند"],"ddx":[{"n":"Retrobulbar hemorrhage / orbital compartment syndrome |","cm":1},{"n":"Hyphema / lens dislocation / retinal detachment |"}],"redflags":["مردمک اشک‌قطره‌ای، Seidel مثبت، نابینایی، خروج محتوای کره"],"guide":"blowout: CT اربیت با برش 1.5 mm؛ آنتی‌بیوتیک پروفیلاکسی cephalexin 250 تا 500 mg PO چهار بار روزانه × 10 روز (درگیری سینوس)؛ ارجاع همه blowout منفرد به چشم‌پزشک برای معاینه با گشادکردن مردمک. ruptured globe: هیچ دستکاری/معاینه بیشتر ممنوع؛ شیلد محافظ فوراً، بیمار نشسته و NPO؛ آنتی‌بیوتیک وسیع‌الطیف + ضداستفراغ برای جلوگیری از افزایش IOP با استفراغ؛ کزاز؛ CT اربیت در موارد نامشخص (حساسیت پایین برای آسیب پنهان)؛ تماس فوری چشم‌پزشک.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 149: Eye Emergencies, pp. 813–825"},"chemical-eye-injury":{"id":"chemical-eye-injury","variants":[{"id":"chemical-eye-main","o":{"L":[{"t":"pH of lower cul-de-sac (litmus paper / urine dipstick) 5–10 min after pausing irrigation; recheck every 10 min × 30 min; IOP"}],"S":[{"t":"Sterile normal saline or Ringer lactate irrigation immediately (before acuity / registration) with topical anesthetic and Morgan lens until pH ~7.4 and stable 30 min (often > 8–10 L; first 2 L then pH check)","fl":[{"k":"hi","v":""}]},{"t":"Cyclopentolate 1% one drop three times daily; erythromycin 0.5% ophthalmic ointment every 1–2 h while awake; opioid analgesia"}],"T":[{"t":"Remove particles from fornices with moistened cotton-tipped applicator; evert lids; slit lamp; update tetanus"},{"t":"Cyanoacrylate glue: heavy erythromycin 0.5% ointment for manual removal; discharge with ointment five times a day"}],"Co":[{"t":"Ophthalmology immediately for severe injury (chemosis, blanching, epithelial defect, corneal edema / opacification, elevated IOP) or HF / lye / concrete; otherwise telephone consult and follow-up within 24 h"}]},"name":"Chemical eye burn (and cyanoacrylate exposure)","level":"I","imp":"Chemical ocular injury","cond":"Emergent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۲۵ ساله پس از پاشیده شدن قلیای تمیزکننده به چشم با درد شدید و بلفاروسپاسم.","why":"شستشوی فوری قبل از هر چیز تا pH نرمال."}],"ch":"149","name":"Chemical ocular injury (acid and alkali burns)","name_fa":"سوختگی شیمیایی چشم (اسید و قلیا)","cc":["eye","burn-electrical"],"keywords":"chemical eye burn, alkali burn, acid burn, ocular irrigation, Morgan lens, pH, cyclopentolate, سوختگی شیمیایی چشم","status":"draft","features":["اسید و قلیا مشابه مدیریت می‌شوند؛ شستشو فوری در صحنه و ادامه در ED بلافاصله پس از ورود (حتی قبل از حدت بینایی یا ثبت)"],"ddx":[{"n":"Ocular hydrofluoric acid / lye / cement burns |","cm":1},{"n":"Corneal abrasion / ulcer |"}],"redflags":["chemosis شدید، blanching ملتحمه، نقص اپیتلیال، ادم یا کدورت قرنیه، IOP بالا"],"guide":"شستشو با NS استریل یا Ringer lactate تا pH نزدیک 7.4؛ بی‌حسی موضعی و Morgan lens؛ پس از 2 L اول، pH با litmus یا نوار ادرار در cul-de-sac تحتانی 5 تا 10 دقیقه پس از توقف شستشو؛ ادامه تا pH نرمال 30 دقیقه پس از توقف؛ حجم ممکن > 8 تا 10 L؛ pH مداوم غیرطبیعی: برداشتن ذرات بلوری در fornices با اپلیکاتور مرطوب؛ پس از pH نرمال: ورتکس پلک و برداشتن ذرات/ملتحمه نکروتیک؛ کنترل مجدد pH هر 10 دقیقه × 30 دقیقه؛ slit lamp کامل؛ IOP. cyclopentolate 1% یک قطره 3 بار روزانه برای اسپاسم مژگانی؛ erythromycin 0.5% ointment هر 1 تا 2 ساعت در بیداری؛ اغلب اوپیوئید؛ کزاز. علائم شدید: چشم‌پزشک در ED؛ HF، لای (lye) یا سیمان: فوراً چشم‌پزشک؛ سایر: تلفن به چشم‌پزشک و پیگیری 24 ساعت. چسب سیانوآکریلات (Super Glue): erythromycin 0.5% ointment فراوان برای برداشتن دستی و ترخیص با ointment 5 بار روزانه؛ برداشتن کامل توسط چشم‌پزشک 24 ساعت بعد.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 149: Eye Emergencies, pp. 813–825"},"acute-angle-closure-glaucoma":{"id":"acute-angle-closure-glaucoma","variants":[{"id":"acute-glaucoma-main","o":{"L":[{"t":"IOP measurement (tonometry); electrolytes, BUN, creatinine (before acetazolamide / mannitol); sickle cell status if relevant"}],"S":[{"t":"Timolol 0.5% one drop; apraclonidine 1% one drop (wait 1 min between drops)","fl":[{"k":"ci","v":"timolol — asthma / COPD / bradycardia / heart block"}]},{"t":"Acetazolamide 500 mg PO (or IV if IOP > 50 mmHg, severe vision loss, or cannot tolerate PO)","fl":[{"k":"ci","v":"sickle cell disease; sulfa allergy"}]},{"t":"Mannitol 1–2 g/kg IV if IOP remains ≥ 40 mmHg 30 min after treatment started","fl":[{"k":"ci","v":"heart failure / renal failure"}]},{"t":"Pilocarpine 1–2% one drop every 15 min for two doses in affected eye (0.5% contralateral eye) once IOP < 40 mmHg, then four times daily (some give immediately)"},{"t":"Antiemetic and analgesia"}],"T":[{"t":"Patient supine; recheck IOP hourly; avoid mydriatics"}],"Co":[{"t":"Immediate ophthalmology consultation; disposition / further therapy by ophthalmologist at bedside (laser iridotomy)"}]},"name":"Acute angle-closure glaucoma","level":"I","imp":"Acute angle-closure glaucoma","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"زن ۶۵ ساله پس از دیدن فیلم در سینما با درد شدید چشم راست، هاله رنگی، استفراغ و مردمک نیمه‌گشاده ثابت؛ IOP 55.","why":"کاهش IOP فوری همزمان با چشم‌پزشک."}],"ch":"149","name":"Acute angle-closure glaucoma","name_fa":"گلوکوم حاد زاویه بسته","cc":["eye","headache"],"keywords":"acute angle closure glaucoma, intraocular pressure, timolol, apraclonidine, acetazolamide, mannitol, pilocarpine, glaucoma, گلوکوم حاد","status":"draft","features":["درد شدید ناگهانی چشم و/یا سردرد، تاری/کدری دید، هاله رنگی دور نور، استفراغ؛ تحریک: سینما، مطالعه، داروی گشادکننده مردمک، آنتی‌کولینرژیک استنشاقی یا کوکائین؛ معاینه: احتقان ملتحمه، کدورت قرنیه، مردمک نیمه‌گشاد و ثابت، IOP 40 تا 70 mmHg (نرمال 10 تا 20)"],"ddx":[{"n":"Iritis / corneal ulcer |","cm":1},{"n":"Migraine / cluster headache / SAH |"}],"redflags":["IOP > 50، کاهش شدید بینایی، استفراغ"],"guide":"مشاوره فوری چشم‌پزشکی؛ همزمان کاهش IOP (جدول 149-3): بیمار supine (بین قطره‌ها 1 دقیقه): timolol 0.5% یک قطره؛ apraclonidine 1% یک قطره؛ acetazolamide 500 mg PO یا IV (منع: سلول داسی و آلرژی سولفا؛ IV اگر IOP > 50، کاهش شدید بینایی یا عدم تحمل PO)؛ اگر IOP ≥ 40 بعد از 30 دقیقه: mannitol 1 تا 2 g/kg IV؛ پایش IOP هر ساعت؛ pilocarpine 1% تا 2% یک قطره هر 15 دقیقه × 2 دوز چشم مبتلا و pilocarpine 0.5% چشم مقابل وقتی IOP < 40 (بعضی بلافاصله) سپس 4 بار روزانه؛ درمان درد و تهوع؛ تصمیم بعدی توسط چشم‌پزشک بر بالین.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 149: Eye Emergencies, pp. 813–825"},"optic-neuritis":{"id":"optic-neuritis","variants":[{"id":"optic-neuritis-main","o":{"I":[{"t":"MRI brain / orbits with gadolinium (MS workup)"}],"L":[{"t":"ESR / CRP (rule out GCA if > 50), syphilis serology, ANA, B12 as indicated"}],"S":[{"t":"IV methylprednisolone followed by oral taper per ophthalmology / neurology","fl":[{"k":"ci","v":"oral steroids alone increase recurrence"}]}],"T":[{"t":"Visual acuity, color vision (red desaturation), pupils (APD), fundus, visual fields"}],"Co":[{"t":"Ophthalmology-directed evaluation; neurology (MS workup); admit per consult"}]},"name":"Optic neuritis","level":"II","imp":"Optic neuritis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۳۰ ساله با کاهش بینایی یک‌چشمی طی 3 روز، درد با حرکت چشم، APD و کاهش دید رنگ.","why":"ورک‌آپ MS و استروئید IV با چشم‌پزشک."}],"ch":"149","name":"Optic neuritis","name_fa":"نوریت اپتیک","cc":["eye","focal-neuro"],"keywords":"optic neuritis, red desaturation, afferent pupillary defect, multiple sclerosis, IV methylprednisolone, نوریت بینایی","status":"draft","features":["التهاب در هر نقطه عصب بینایی: کاهش حاد بینایی با کاهش ویژه بینایی رنگ؛ ارتباط قوی با MS ولی علل دیگر (سیفلیس، TB، سارکوئید)؛ اغلب بی‌درد ولی گاه دردناک با حرکات چشم","red desaturation test: نگاه با یک چشم به جسم قرمز تیره: چشم مبتلا آن را صورتی/کم‌رنگ می‌بیند؛ APD؛ نقص میدان بینایی؛ نوریت قدامی: پاپیلیت (ادم دیسک)؛ retrobulbar: بدون یافته افتالموسکوپیک"],"ddx":[{"n":"Giant cell arteritis / CRAO / retinal detachment |","cm":1},{"n":"Compressive optic neuropathy / MS |"}],"redflags":["از دست رفتن بینایی، APD، سن > 50 (GCA)"],"guide":"ارزیابی و درمان با هدایت چشم‌پزشک؛ IV steroid سپس خوراکی بهبود بینایی را تسریع و موقتاً خطر MS را کم می‌کند ولی استروئید خوراکی تنها عود ON را افزایش می‌دهد؛ تشخیص جدید ON ← ورک‌آپ MS و علل دیگر.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 149: Eye Emergencies, pp. 813–825"},"central-retinal-artery-occlusion":{"id":"central-retinal-artery-occlusion","variants":[{"id":"crao-main","o":{"I":[{"t":"Carotid imaging (duplex / CTA / MRA); brain imaging (stroke) per stroke protocol; echocardiography as indicated"}],"L":[{"t":"ESR, CRP (exclude giant cell arteritis), CBC, glucose, lipid panel, coagulation, troponin; ECG (AF)"}],"S":[{"t":"Management per ophthalmologist / institutional protocol (digital massage, acetazolamide, timolol — sparse evidence)"},{"t":"If giant cell arteritis suspected: methylprednisolone 250 mg IV every 6 h (admission)"}],"T":[{"t":"Cardiac monitor; stroke work-up (embolic source)"}],"Co":[{"t":"Immediate ophthalmology; neurology / stroke team; admit"}]},"name":"Central retinal artery occlusion","level":"I","imp":"Central retinal artery occlusion","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"none","sc":"مرد ۶۸ ساله با از دست رفتن ناگهانی بینایی چشم راست 2 ساعت پیش؛ APD و cherry red spot.","why":"ورک‌آپ آمبولیک و GCA؛ چشم‌پزشک فوراً."}],"ch":"149","name":"Central retinal artery occlusion (CRAO)","name_fa":"انسداد شریان مرکزی شبکیه (CRAO)","cc":["eye","focal-neuro"],"keywords":"central retinal artery occlusion, CRAO, cherry red spot, amaurosis fugax, boxcarring, embolic, giant cell arteritis, انسداد شریان شبکیه","status":"draft","features":["از دست رفتن ناگهانی، بدون درد و شدید بینایی یک‌چشمی؛ اغلب سابقه amaurosis fugax؛ انسداد شریان مرکزی: از دست رفتن کامل بینایی؛ انسداد شاخه: نقص ناگهانی بخشی میدان؛ علائم کلاسیک: بینایی تقریباً/کاملاً از بین (94% counting fingers تا light perception)، APD واضح، سفیدی سطحی شبکیه قطب خلفی و «cherry red spot» ماکولا؛ segmentation ستون خون (boxcarring)","ارزیابی علت (آمبولی کاروتید/قلبی، واسکولیت، هیپرکوآگولابل)؛ رد GCA"],"ddx":[{"n":"Giant cell arteritis / stroke (embolic) |","cm":1},{"n":"Retinal detachment / CRVO / optic neuritis |"}],"redflags":["کاهش ناگهانی بی‌درد بینایی، سن > 50 (GCA)، سابقه AF"],"guide":"تماس فوری با چشم‌پزشک پس از تشخیص. ماساژ دیجیتال، acetazolamide و timolol قبلاً توصیه می‌شد ولی شواهد کم؛ مدیریت با پروتکل مؤسسه و چشم‌پزشک.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 149: Eye Emergencies, pp. 813–825"},"central-retinal-vein-occlusion":{"id":"central-retinal-vein-occlusion","variants":[{"id":"crvo-main","o":{"L":[{"t":"CBC, glucose, lipids, ESR, coagulation / thrombophilia screen as indicated; BP check"}],"T":[{"t":"Discontinue predisposing drugs (oral contraceptives, diuretics); control BP / glucose"}],"Co":[{"t":"Ophthalmology consultation"}]},"name":"Central retinal vein occlusion","level":"II","imp":"Central retinal vein occlusion","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"زن ۵۵ ساله با کاهش ناگهانی بینایی یک چشم، خونریزی‌های منتشر شبکیه و ادم دیسک.","why":"قطع داروهای مستعدکننده و ارجاع."}],"ch":"149","name":"Central retinal vein occlusion (CRVO)","name_fa":"انسداد ورید مرکزی شبکیه (CRVO)","cc":["eye"],"keywords":"central retinal vein occlusion, CRVO, blood and thunder fundus, cotton wool spots, انسداد ورید شبکیه","status":"draft","features":["ترومبوز ورید مرکزی: کاهش ناگهانی بی‌درد بینایی یک‌چشمی؛ ادم دیسک، cotton wool و خونریزی شبکیه در هر چهار ربع («blood-and-thunder fundus»)؛ APD"],"ddx":[{"n":"CRAO / retinal detachment / vitreous hemorrhage |","cm":1},{"n":"Hyperviscosity / diabetic retinopathy |"}],"redflags":["کاهش ناگهانی بینایی"],"guide":"درمان فوری ندارد؛ داروهای مستعدکننده (OCP، دیورتیک) قطع شود؛ مشاوره چشم‌پزشکی.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 149: Eye Emergencies, pp. 813–825"},"retinal-detachment":{"id":"retinal-detachment","variants":[{"id":"retinal-detachment-main","o":{"I":[{"t":"Bedside ocular ultrasonography (retinal detachment; keep pressure minimal and duration limited)"}],"T":[{"t":"Visual acuity, visual fields, dilated exam by ophthalmology; limit activity"}],"Co":[{"t":"Urgent ophthalmology consultation (indirect ophthalmoscopy; possible laser surgery); isolated new floaters: follow-up ≤ 24 h"}]},"name":"Suspected retinal detachment","level":"II","imp":"Retinal detachment","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۵۵ ساله نزدیک‌بین با برق‌زدن و پرده تیره در گوشه میدان بینایی چشم راست.","why":"سونوگرافی بالین و چشم‌پزشکی فوری."}],"ch":"149","name":"Retinal detachment, floaters and flashes","name_fa":"جداشدگی شبکیه، floaters و برق‌زدن","cc":["eye"],"keywords":"retinal detachment, floaters, flashes of light, curtain, ocular ultrasonography, جداشدگی شبکیه, لکه شناور","status":"draft","features":["تغییر ناگهانی بینایی؛ علائم دوطرفه تقریباً همیشه منشأ داخل‌جمجمه‌ای (مثلاً میگرن)؛ یک‌چشمی معمولاً بیماری همان چشم","RD: برق‌زدن ناگهانی، floaters و پرده/پرده‌ی تیره در میدان بینایی چشم مبتلا؛ تشخیص اولیه: سونوگرافی بالین؛ floaters جدید (ذرات ژل ویتره: کدورت‌های مه‌آلود کوچک) فوریت ندارد و دیلاته توسط چشم‌پزشک ≤ 24 ساعت"],"ddx":[{"n":"CRAO / vitreous hemorrhage |","cm":1},{"n":"Migraine aura (bilateral) / posterior vitreous detachment |"}],"redflags":["پرده تیره، برق‌زدن مکرر، کاهش بینایی"],"guide":"مشاوره فوری چشم‌پزشکی برای افتالموسکوپی غیرمستقیم و احتمالاً لیزر. floaters ایزوله: پیگیری مطب ≤ 24 ساعت.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 149: Eye Emergencies, pp. 813–825"},"temporal-arteritis-vision":{"id":"temporal-arteritis-vision","variants":[{"id":"gca-vision-loss","o":{"L":[{"t":"ESR, CRP (CRP more sensitive), CBC, glucose, creatinine"}],"S":[{"t":"Methylprednisolone 250 mg IV every 6 h (admit)","fl":[{"k":"hi","v":""},{"k":"ci","v":"diabetes — monitor glucose; peptic ulcer"}]},{"t":"Antiulcer medication (PPI) with systemic steroids"}],"T":[{"t":"Fundus exam; do not delay steroids for biopsy; temporal artery biopsy arranged"}],"Co":[{"t":"Admit; ophthalmology; rheumatology / neurology; temporal artery biopsy"}]},"name":"Giant cell arteritis with vision loss or strong suspicion","level":"I","imp":"Temporal arteritis with visual loss","cond":"Emergent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"زن ۷۵ ساله با از دست رفتن ناگهانی بینایی چشم چپ، سردرد تمپورال، claudication فک و ESR 95.","why":"استروئید IV بلافاصله بدون انتظار بیوپسی."},{"id":"gca-no-vision-loss","o":{"L":[{"t":"ESR, CRP, CBC, glucose"}],"S":[{"t":"Prednisone 80–100 mg/day PO (do not delay for biopsy)","fl":[{"k":"ci","v":"diabetes — glucose monitoring"}]},{"t":"Antiulcer medication with systemic steroids"}],"Co":[{"t":"Close follow-up; temporal artery biopsy / ophthalmology / rheumatology"}]},"name":"Suspected giant cell arteritis without vision loss","level":"II","imp":"Suspected temporal arteritis, no vision loss","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۶۸ ساله با سردرد تمپورال جدید، حساسیت شریان و خستگی؛ بینایی طبیعی؛ ESR 80.","why":"پردنیزون خوراکی با پیگیری نزدیک."}],"ch":"149","name":"Temporal arteritis (giant cell arteritis) with ischemic optic neuropathy","name_fa":"آرتریت تمپورال با نوروپاتی ایسکمیک عصب بینایی","cc":["eye","headache"],"keywords":"giant cell arteritis, temporal arteritis, ischemic optic neuropathy, ESR, CRP, methylprednisolone, آرتریت تمپورال, بینایی","status":"draft","features":["واسکولیت سیستمیک با نوروپاتی اپتیک ایسکمیک بی‌درد؛ معمولاً زن > 50 سال، اغلب سابقه polymyalgia rheumatica؛ علائم: تغییر بینایی، سردرد، claudication فک، حساسیت پوست سر/شریان تمپورال، خستگی، تب، گلودرد، URI، بی‌اشتهایی؛ معمولاً یک‌طرفه ولی ممکن دوطرفه؛ یک‌سوم با TIA/سکته؛ APD شایع؛ فوندوس: flame hemorrhage؛ فلج عصب 6","ESR و CRP (CRP حساس‌تر)؛ بیوپسی اثبات‌شده معمولاً ESR 70 تا 110؛ بدون درمان: از دست رفتن دوطرفه بینایی"],"ddx":[{"n":"CRAO / optic neuritis / stroke |","cm":1},{"n":"Migraine / other causes of AION |"}],"redflags":["کاهش بینایی، APD، ESR/CRP بالا، claudication فک"],"guide":"شک قوی یا کاهش بینایی: بستری و methylprednisolone 250 mg IV هر 6 ساعت. شک کمتر بدون کاهش بینایی: ترخیص با prednisone 80 تا 100 mg/d PO و پیگیری نزدیک. استروئید نباید منتظر بیوپسی بماند. داروی ضدزخم همراه استروئید سیستمیک.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 149: Eye Emergencies, pp. 813–825"},"ocular-ultrasonography-note":{"id":"ocular-ultrasonography-note","variants":[{"id":"ocular-pocus-main","o":{"I":[{"t":"Ocular ultrasonography (avoid pressure on eye / eyelid if globe rupture suspected; strictly limit duration)"}],"T":[{"t":"Linear high-frequency probe over closed eyelid with generous gel"}],"Co":[{"t":"Ophthalmology for positive findings"}]},"name":"Ocular ultrasonography (retinal detachment / retrobulbar hematoma / lens dislocation / vitreous hemorrhage)","level":"III","imp":"Ocular point-of-care ultrasonography","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"بیمار با کاهش بینایی ناگهانی که تشخیص قطعی ندارد؛ نیاز به غربال سریع.","why":"تشخیص سریع RD و هماتوم retrobulbar."}],"ch":"149","name":"Point-of-care ocular ultrasonography — applications and cautions","name_fa":"سونوگرافی بالینی چشم — کاربردها و احتیاط","cc":["eye"],"keywords":"ocular ultrasound, POCUS eye, retinal detachment, lens dislocation, vitreous hemorrhage, optic nerve sheath, سونوگرافی چشم","status":"draft","features":["سونوگرافی چشم برای ارزیابی اورژانس چشم به‌ویژه در تروما: جداشدگی شبکیه، هماتوم retrobulbar، دررفتگی عدسی، خونریزی ویتره و افزایش ICP؛ فشار روی چشم یا پلک در شک پارگی کره اجتناب و مدت محدود"],"ddx":[{"n":"Ruptured globe (avoid pressure) |","cm":1}],"redflags":["شک پارگی کره (بدون فشار)"],"guide":"در سونوگرافی چشم از هر فشار روی کره/پلک بپرهیز اگر پارگی کره مشکوک؛ مدت معاینه کاملاً محدود.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 149: Eye Emergencies, pp. 813–825"},"facial-cellulitis-erysipelas-impetigo":{"id":"facial-cellulitis-erysipelas-impetigo","variants":[{"id":"facial-cellulitis-outpatient","o":{"I":[{"t":"Ultrasound or CT if abscess / extensive infection suspected"}],"A":[{"t":"Cellulitis: cephalexin 500 mg PO four times daily, or dicloxacillin 500 mg four times daily, or clindamycin 300–450 mg four times daily; suspected MRSA: trimethoprim-sulfamethoxazole 1–2 DS tablets twice daily, or doxycycline 100 mg twice daily, or minocycline 100 mg twice daily (total 7–10 days)"},{"t":"Erysipelas: penicillin V 500 mg PO four times daily; if MSSA suspected amoxicillin/clavulanate 875/125 mg twice daily, cephalexin or dicloxacillin; bullous: TMP-SMX, clindamycin, doxycycline or minocycline (7–10 days)","fl":[{"k":"ci","v":"allergy / renal impairment dose adjust"}]}],"T":[{"t":"Mark border; warm compresses; elevation; analgesia"}],"Co":[{"t":"Follow-up 24–48 h; admit if systemic illness, failure of outpatient therapy, immunocompromise"}]},"name":"Facial cellulitis / erysipelas, nontoxic (oral antibiotics)","level":"III","imp":"Facial cellulitis / erysipelas","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۴۵ ساله با قرمزی، تورم و گرمی گونه از 2 روز پس از خراش؛ بدون تب و سمیت.","why":"آنتی‌بیوتیک خوراکی 7 تا 10 روز؛ پوشش MRSA در شک."},{"id":"facial-cellulitis-iv","o":{"I":[{"t":"CT neck / face with contrast (abscess / deep infection)"}],"L":[{"t":"CBC, glucose, creatinine, CRP; blood cultures if systemic illness"}],"A":[{"t":"Parenteral: vancomycin 1 g IV every 12 h, or clindamycin 600 mg IV every 8 h; erysipelas: nafcillin 1–2 g IV every 4 h, or cefazolin 1 g IV every 8 h, or penicillin G 2–3 million units every 6 h"}],"S":[{"t":"IV fluids if dehydrated","fl":[{"k":"ci","v":"caution in heart failure / CKD"}]}],"Co":[{"t":"Admit; ENT / ophthalmology if periorbital / deep extension"}]},"name":"Facial cellulitis / erysipelas with systemic illness or failed outpatient therapy (parenteral)","level":"II","imp":"Facial cellulitis, parenteral therapy","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"زن ۵۵ ساله دیابتی با سلولیت صورت، تب 38.8 و تاکی‌کاردی با پیشرفت علی‌رغم خوراکی.","why":"تزریقی و جستجوی عمق/آبسه."},{"id":"impetigo-main","o":{"A":[{"t":"Simple nonbullous: mupirocin 2% ointment to lesions three times daily (or retapamulin 1% twice daily) for 7 days"},{"t":"Extensive or bullous: oral dicloxacillin 500 mg four times daily, amoxicillin/clavulanate 875/125 mg twice daily, or cephalexin 500 mg four times daily; MRSA suspected: clindamycin or TMP-SMX (total 7 days)"}],"T":[{"t":"Hygiene; cover lesions"}],"Co":[{"t":"Follow-up if no improvement"}]},"name":"Impetigo (bullous / nonbullous)","level":"III","imp":"Impetigo","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"کودک ۵ ساله با کراست کهربایی دور بینی و دهان.","why":"موضعی برای ساده؛ خوراکی در گسترده یا بولوس."}],"ch":"150","name":"Facial cellulitis, erysipelas and impetigo","name_fa":"سلولیت صورت، erysipelas و ایمپتیگو","cc":["rash","fever","ent"],"keywords":"facial cellulitis, erysipelas, impetigo, MRSA, mupirocin, retapamulin, cephalexin, clindamycin, trimethoprim-sulfamethoxazole, سلولیت صورت, ایمپتیگو","status":"draft","features":["سلولیت: عفونت پوست و زیرجلد؛ معمولاً S. pyogenes و S. aureus با غلبه فزاینده MRSA؛ گاه گسترش از عفونت عمیق‌تر؛ اریتم، ادم، گرمی، درد و از دست رفتن عملکرد؛ مرز مشخص قابل لمس ندارد؛ تشخیص بالینی؛ سونوگرافی/CT برای آبسه یا عفونت گسترده","erysipelas: سلولیت سطحی (اپیدرم، درم فوقانی و لنفاتیک)؛ بیشتر S. pyogenes؛ S. aureus نادر ولی همراه بولوس، تروما یا جسم خارجی؛ قرمز، برجسته، پف‌آلود با مرز مشخص و قابل لمس","ایمپتیگو: عفونت سطحی اپیدرم: بولوس (S. aureus) و غیربولوس (S. aureus و S. pyogenes)؛ غیربولوس: راش اریتماتو با وزیکول‌هایی که پاره و کراست کهربایی تشکیل می‌دهند؛ بولوس: وزیکول بزرگ‌شده به بول با مایع زرد شفاف"],"ddx":[{"n":"Facial abscess / masticator space infection / orbital cellulitis |","cm":1},{"n":"Necrotizing infection |","cm":1},{"n":"Contact dermatitis / herpes zoster / angioedema |"}],"redflags":["علائم سیستمیک، گسترش به اربیت/عمق، نقص ایمنی، شکست درمان سرپایی"],"guide":"اغلب آنتی‌بیوتیک خوراکی 7 تا 14 روز (جدول‌های 150-1 و 150-2). سلولیت: خوراکی: clindamycin، dicloxacillin یا سفالوسپورین؛ مشکوک MRSA: TMP-SMX، clindamycin، doxycycline یا minocycline؛ تزریقی: vancomycin، clindamycin؛ کل 7 تا 10 روز. erysipelas: خوراکی: penicillin؛ MSSA مشکوک: amoxicillin/clavulanate، cephalexin، dicloxacillin؛ بولوس: TMP-SMX، clindamycin، doxycycline یا minocycline؛ تزریقی: vancomycin، nafcillin، clindamycin؛ 7 تا 10 روز. ایمپتیگو: موضعی: mupirocin یا retapamulin ointment به‌تنهایی یا با خوراکی؛ خوراکی: dicloxacillin، amoxicillin/clavulanate، cephalexin؛ MRSA: clindamycin یا TMP-SMX؛ 7 روز. دوزها (جدول 150-2): mupirocin 2% سه بار روزانه؛ retapamulin 1% دو بار؛ amoxicillin/clavulanate 875/125 mg دو بار؛ cephalexin 500 mg چهار بار؛ clindamycin 300 تا 450 mg چهار بار؛ dicloxacillin 500 mg چهار بار؛ doxycycline 100 mg دو بار؛ metronidazole 500 mg هر 8 ساعت؛ minocycline 100 mg دو بار؛ penicillin V 500 mg چهار بار؛ TMP-SMX DS 1 تا 2 قرص دو بار؛ تزریقی: ampicillin-sulbactam 1.5 تا 3.0 g هر 6 ساعت؛ clindamycin 600 mg هر 8 ساعت؛ cefazolin 1 g هر 8 ساعت؛ metronidazole 1 g بار سپس 500 mg هر 8 ساعت؛ nafcillin 1 تا 2 g هر 4 ساعت؛ penicillin G 2 تا 3 میلیون واحد هر 6 ساعت؛ vancomycin 1 g هر 12 ساعت. بستری و تزریقی: علائم سیستمیک، شکست سرپایی، بیماری همراه مهم، نقص ایمنی.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 150: Face and Jaw Emergencies, pp. 826–830"},"parotitis-mumps-suppurative":{"id":"parotitis-mumps-suppurative","variants":[{"id":"parotitis-viral","o":{"L":[{"t":"(clinical diagnosis; lipase if abdominal pain; mumps PCR / serology for public health)"}],"T":[{"t":"Supportive care: analgesics / antipyretics, hydration; isolation approximately 9 days from onset of swelling"},{"t":"Examine testes (orchitis), neurologic status (meningitis), hearing"}],"Co":[{"t":"Admit for systemic complications; public health notification"}]},"name":"Viral parotitis (mumps)","level":"III","imp":"Viral parotitis (mumps)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۲۰ ساله با تب، سردرد و تورم دردناک دوطرفه پاروتید بدون اریتم.","why":"حمایتی و جدا کردن 9 روزه؛ عوارض را بررسی کن."},{"id":"parotitis-suppurative","o":{"I":[{"t":"Ultrasound or CT if abscess suspected"}],"L":[{"t":"CBC, electrolytes, glucose, creatinine; culture of ductal pus"}],"S":[{"t":"IV fluids for dehydration","fl":[{"k":"ci","v":"caution in heart failure / CKD"}]}],"A":[{"t":"Oral (tolerating PO, no trismus): amoxicillin-clavulanate 875/125 mg twice daily, or clindamycin 300–450 mg four times daily, or cephalexin 500 mg four times daily + metronidazole 500 mg every 8 h (10–14 days)"},{"t":"Parenteral: nafcillin 1–2 g IV every 4 h, ampicillin-sulbactam 1.5–3 g IV every 6 h, or vancomycin 1 g IV every 12 h with metronidazole 1 g load then 500 mg IV every 8 h (hospital-acquired / nursing home: include vancomycin)"}],"T":[{"t":"Sialogogues (lemon drops); stop medications causing dry mouth (diuretics, β-blockers, antihistamines, phenothiazines, TCAs); warm compresses; gland massage"}],"Co":[{"t":"Admit if systemic illness, immunocompromise, unable to take PO or outpatient failure; close follow-up; ENT"}]},"name":"Suppurative parotitis","level":"II","imp":"Suppurative parotitis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۸۰ ساله دهیدراته با تب، تورم قرمز و دردناک پاروتید و چرک از مجرای Stensen.","why":"آنتی‌بیوتیک، هیدراتاسیون و sialogogue."},{"id":"sialolithiasis-main","o":{"T":[{"t":"Analgesics; gland massage; sialogogues (lemon drops); palpable stone may be milked from duct"},{"t":"Antibiotics only if concurrent infection suspected (as for suppurative parotitis)"}],"Co":[{"t":"ENT referral for persistent retained calculi"}]},"name":"Sialolithiasis","level":"III","imp":"Sialolithiasis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۴۰ ساله با درد و تورم زیر فک چپ که هنگام غذا خوردن بدتر می‌شود.","why":"ضددرد، ماساژ و sialogogue."}],"ch":"150","name":"Parotitis (viral / mumps and suppurative) and sialolithiasis","name_fa":"پاروتیت (ویروسی/اوریون و چرکی) و سنگ غده بزاقی","cc":["ent","fever"],"keywords":"mumps, viral parotitis, suppurative parotitis, Stensen duct, sialolithiasis, sialogogue, lemon drops, اوریون, پاروتیت, سنگ بزاقی","status":"draft","features":["ویروسی (اوریون): تورم یک یا دوطرفه پاروتید؛ معمولاً paramyxovirus؛ prodrome تب، بی‌حالی، میالژی، سردرد؛ غده سفت و دردناک ولی بدون اریتم و گرمی؛ چرک از مجرای Stensen خارج نمی‌شود؛ تشخیص بالینی؛ تورم تا 5 روز؛ مسری حدود 9 روز پس از شروع تورم؛ اورکیت 20 تا 30% مردان، اووفوریت 5% زنان؛ پانکراتیت، منژیت آسپتیک، کم‌شنوایی، میوکاردیت، آرتریت، آنمی همولیتیک، ترومبوسیتوپنی","چرکی: عفونت باکتریال در کاهش جریان بزاق (بیهوشی اخیر، دهیدراتاسیون، نارس بودن، سن بالا، داروها (دیورتیک، β-blocker، آنتی‌هیستامین، فنوتیازین، TCA)، Sjögren، دیابت، هیپوتیروئیدی، CF، HIV)؛ تب، trismus، اریتم و درد؛ چرک از مجرای Stensen؛ سونوگرافی/CT در شک آبسه","سنگ بزاقی (sialolithiasis): 80% مجرای submandibular؛ معمولاً یک‌طرفه؛ درد، تورم و حساسیت که با غذا خوردن تشدید می‌شود؛ سنگ در مجرا قابل لمس و غده سفت"],"ddx":[{"n":"Masticator space abscess / Ludwig angina |","cm":1},{"n":"Dental infection |","cm":1},{"n":"Sjögren syndrome / tumor / HIV parotitis |"}],"redflags":["trismus، علائم سیستمیک، عدم تحمل خوراکی، نقص ایمنی"],"guide":"اوریون: تشخیص بالینی و درمان حمایتی؛ بستری برای عوارض سیستمیک. چرکی: بهینه کردن جریان بزاق با sialogogue (آبنبات لیمو) و قطع داروهای خشکی دهان؛ آنتی‌بیوتیک خوراکی برای تحمل خوراکی و بدون trismus (جدول 150-1: amoxicillin-clavulanate، clindamycin یا cephalexin + metronidazole)؛ تزریقی: nafcillin، ampicillin-sulbactam یا vancomycin + metronidazole؛ بیمارستانی/خانه سالمندان: شامل vancomycin؛ 10 تا 14 روز؛ بستری: سمیت سیستمیک، نقص ایمنی، عدم تحمل خوراکی یا شکست سرپایی؛ پیگیری نزدیک. سنگ: ضددرد، ماساژ، sialogogue و آنتی‌بیوتیک اگر عفونت همزمان؛ سنگ قابل لمس را از مجرا بدوشید؛ سنگ باقی‌مانده توسط ENT.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 150: Face and Jaw Emergencies, pp. 826–830"},"masticator-space-abscess":{"id":"masticator-space-abscess","variants":[{"id":"masticator-abscess-main","o":{"I":[{"t":"Contrast-enhanced CT neck / face; CXR PA (mediastinal extension)"}],"L":[{"t":"CBC, electrolytes, glucose, creatinine, CRP, blood cultures; lactate if septic"}],"S":[{"t":"IV fluids","fl":[{"k":"ci","v":"caution in heart failure"}]}],"A":[{"t":"Clindamycin 600 mg IV every 8 h ; alternatives: ampicillin-sulbactam 1.5–3 g IV every 6 h, cefoxitin, or penicillin G 2–3 million units every 6 h + metronidazole 500 mg every 8 h (10–14 days)","fl":[{"k":"hi","v":""}]}],"T":[{"t":"Airway assessment (trismus, floor of mouth); analgesia"}],"Co":[{"t":"Otolaryngology / oral and maxillofacial surgery consult (drainage); admit"}]},"name":"Masticator space abscess","level":"I","imp":"Masticator space abscess","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"PA","sc":"مرد ۴۰ ساله با پوسیدگی دندان، تورم صورت، trismus و تب 38.5.","why":"CT با کنتراست، clindamycin IV و ENT/OMFS."}],"ch":"150","name":"Masticator space abscess (odontogenic deep neck infection)","name_fa":"آبسه فضای ماستیکاتور","cc":["ent","fever"],"keywords":"masticator space abscess, odontogenic infection, trismus, deep neck infection, contrast CT, clindamycin, آبسه ماستیکاتور, تریسموس","status":"draft","features":["فضاهای بالقوه محدود به عضلات جونده؛ معمولاً پلی‌میکروبیال و منشأ دندانی؛ تورم صورت، درد، اریتم و trismus؛ پیشرفته: سپسیس؛ تشخیص: CT با کنتراست؛ فضاها به صفحات بافتی تا مدیاستن ارتباط دارند ← درمان زودهنگام ضروری"],"ddx":[{"n":"Ludwig angina / retropharyngeal abscess / mediastinitis |","cm":1},{"n":"Parotitis / facial cellulitis / TMJ disorder |"}],"redflags":["trismus، مشکل بلع/راه هوایی، سپسیس"],"guide":"درمان ED: تثبیت، آنتی‌بیوتیک، مشاوره ENT و بستری. تزریقی (جدول 150-1): clindamycin IV توصیه؛ جایگزین‌ها: ampicillin-sulbactam، cefoxitin یا penicillin + metronidazole؛ خوراکی: clindamycin یا amoxicillin-clavulanate؛ 10 تا 14 روز.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 150: Face and Jaw Emergencies, pp. 826–830"},"tmj-trigeminal-neuralgia":{"id":"tmj-trigeminal-neuralgia","variants":[{"id":"tmj-main","o":{"I":[{"t":"(acute trauma only: CT or panoramic x-ray)"}],"S":[{"t":"Analgesics (NSAIDs)","fl":[{"k":"ci","v":"renal disease, GI bleeding"}]}],"T":[{"t":"Soft diet; heat; avoid wide mouth opening"}],"Co":[{"t":"Dental / oral and maxillofacial referral"}]},"name":"TMJ dysfunction","level":"III","imp":"Temporomandibular joint dysfunction","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۳۰ ساله با درد مفصل فک و عضلات جونده و کلیک هنگام جویدن.","why":"ضددرد، رژیم نرم و ارجاع."},{"id":"trigeminal-neuralgia-main","o":{"L":[{"t":"(CBC, sodium, liver function before carbamazepine; HLA-B*1502 where relevant)"}],"S":[{"t":"Carbamazepine 100 mg PO twice daily, increasing as needed","fl":[{"k":"ci","v":"AV block; check ECG; hyponatremia; liver / marrow toxicity"}]}],"Co":[{"t":"Neurology follow-up; MRI outpatient to exclude secondary causes"}]},"name":"Trigeminal neuralgia","level":"III","imp":"Trigeminal neuralgia","cond":"Urgent","act":"CBR","diet":"PO","ecg":"stat","cxr":"none","sc":"زن ۶۰ ساله با حملات درد برق‌مانند ثانیه‌ای گونه راست هنگام صحبت یا غذا خوردن؛ معاینه نرمال.","why":"carbamazepine؛ رد علت ثانویه."}],"ch":"150","name":"Temporomandibular joint dysfunction and trigeminal neuralgia","name_fa":"اختلال مفصل temporomandibular و نورالژی تری‌ژمینال","cc":["ent","headache"],"keywords":"TMJ dysfunction, temporomandibular, trigeminal neuralgia, tic douloureux, carbamazepine, اختلال مفصل فک, نورالژی تری ژمینال","status":"draft","features":["TMJ: ترکیب لولایی و لغزشی؛ اختلال آناتومیک یا بیماری سیستمیک: درد روی عضلات جونده یا ناحیه TMJ و محدودیت حرکت؛ تشخیص بالینی؛ تروما حاد: CT یا پانورکس","trigeminal neuralgia: درد صورت در توزیع عصب پنجم؛ حملات شدید چند ثانیه‌ای با معاینه فیزیکی نرمال"],"ddx":[{"n":"Temporal arteritis / dental pain / sinusitis |","cm":1},{"n":"Cluster headache / herpes zoster |"}],"redflags":["ضعف یا یافته عصبی، سن > 50 با سردرد جدید"],"guide":"TMJ غیرتروماتیک: ضددرد، رژیم نرم و ارجاع دندانپزشکی؛ جراح فک و صورت برای شکستگی. trigeminal neuralgia: carbamazepine با شروع 100 mg PO دو بار روزانه و افزایش بر حسب نیاز.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 150: Face and Jaw Emergencies, pp. 826–830"},"bell-palsy-face":{"id":"bell-palsy-face","variants":[{"id":"bell-palsy-face-main","o":{"S":[{"t":"Prednisone (or equivalent) 1 mg/kg up to 60 mg/day for 6 days followed by a 10-day taper (within 72 h of symptom onset)","fl":[{"k":"ci","v":"diabetes — monitor glucose"}]},{"t":"Ocular lubricants (and eye taping at night) to prevent dry eye"}],"T":[{"t":"Detailed neurologic exam to rule out stroke; examine ear for herpes zoster; antivirals controversial (modest benefit at best)"}],"Co":[{"t":"Follow-up with primary care / ENT"}]},"name":"Bell's palsy","level":"III","imp":"Bell's palsy","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۴۰ ساله با افتادگی ناگهانی نیمه چپ صورت شامل پیشانی از صبح.","why":"استروئید ظرف 72 ساعت و حفاظت چشم."}],"ch":"150","name":"Bell's palsy (facial nerve palsy) — face chapter dosing","name_fa":"فلج بل — دوز فصل صورت","cc":["ent","focal-neuro"],"keywords":"Bell palsy, facial paralysis, prednisone taper, ocular lubricant, فلج بل","status":"draft","features":["شروع حاد فلج یک‌طرفه فوقانی و تحتانی صورت؛ معاینه عصبی دقیق برای رد سکته؛ حفظ عضلات پیشانی ← فرایند مرکزی؛ گوش را برای zoster کرانیال معاینه کن؛ استروئید ظرف 72 ساعت اول شانس بهبود کامل را بالا می‌برد"],"ddx":[{"n":"Stroke (forehead sparing) / Ramsay Hunt / Lyme |","cm":1}],"redflags":["حفظ پیشانی، یافته کانونی دیگر"],"guide":"prednisone یا معادل 1 mg/kg تا 60 mg/d به مدت 6 روز سپس taper 10 روزه؛ ضدویروس بحث‌برانگیز و فایده در حد متوسط؛ روان‌کننده چشمی برای جلوگیری از خشکی چشم.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 150: Face and Jaw Emergencies, pp. 826–830"},"mandible-dislocation":{"id":"mandible-dislocation","variants":[{"id":"mandible-dislocation-anterior","o":{"I":[{"t":"Clinical diagnosis for atraumatic anterior dislocation; panoramic x-ray or CT for all other dislocations / trauma"}],"S":[{"t":"Analgesia and / or muscle relaxant or procedural sedation to facilitate reduction (e.g., IV benzodiazepine / procedural sedation per protocol)"}],"T":[{"t":"Closed reduction: seated patient, padded thumbs over molars, pressure downward and backward"},{"t":"After reduction: do not open mouth more than 2 cm for 2 weeks; soft diet"}],"Co":[{"t":"Elective referral to oral and maxillofacial surgeon; emergent referral for open / nonreducible dislocations, fractures or nerve injury"}]},"name":"Anterior mandible dislocation (atraumatic)","level":"II","imp":"Anterior mandibular dislocation","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"زن ۴۰ ساله پس از خمیازه گسترده با فک قفل‌شده باز، درد و ناتوانی در بستن دهان.","why":"reduction بسته با آنالژزی؛ بدون شکستگی."}],"ch":"150","name":"Mandible dislocation","name_fa":"دررفتگی فک پایین","cc":["ent","limb-injury"],"keywords":"mandibular dislocation, jaw dislocation, TMJ reduction, anterior dislocation, دررفتگی فک","status":"draft","features":["قدامی، خلفی، جانبی یا فوقانی؛ قدامی شایع‌ترین؛ درد، مشکل بلع و malocclusion؛ قدامی: سابقه باز کردن شدید دهان و اشکال حرکت فک؛ سایر: تروما قابل‌توجه"],"ddx":[{"n":"Mandible fracture |","cm":1},{"n":"TMJ dysfunction / temporomandibular arthritis |"}],"redflags":["دررفتگی باز یا غیرقابل جا انداختن، شکستگی، آسیب عصبی"],"guide":"قدامی بدون تروما: تشخیص بالینی؛ تصویربرداری (پانورکس یا CT) برای سایر دررفتگی‌ها. درمان قدامی بدون شکستگی: reduction بسته (با مسکن، شل‌کننده عضلانی یا sedation رویه‌ای)؛ معمولاً بیمار نشسته؛ شست‌ها با گاز پوشیده روی مولارها، فشار پایین و عقب. باز، غیرقابل جا انداختن، شکستگی یا آسیب عصبی: ارجاع اورژانس به OMFS. پس از reduction: دهان را > 2 cm تا 2 هفته باز نکند؛ ارجاع الکتیو OMFS.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 150: Face and Jaw Emergencies, pp. 826–830"},"otitis-externa":{"id":"otitis-externa","variants":[{"id":"otitis-externa-main","o":{"S":[{"t":"Analgesics (acetaminophen / NSAID)"}],"A":[{"t":"Ofloxacin otic 5 drops twice daily for 7 days; or ciprofloxacin/hydrocortisone otic 3 drops twice daily; or acetic acid/hydrocortisone otic 5 drops three times daily","fl":[{"k":"ci","v":"acetic acid / hydrocortisone not with perforated TM"}]},{"t":"Oral antibiotics only if fever or periauricular spread"}],"T":[{"t":"Clean external auditory canal (irrigation with 1:1 hydrogen peroxide:warm saline or gentle suction under visualization); wick or gauze if marked canal swelling; keep ear dry"}],"Co":[{"t":"Follow-up with PCP / ENT if no improvement"}]},"name":"Otitis externa","level":"III","imp":"Otitis externa","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۲۵ ساله پس از شنا با درد گوش، خارش و درد با کشیدن لاله؛ مجرا قرمز و ملتهب.","why":"قطره گوش و تمیز کردن مجرا."}],"ch":"151","name":"Otitis externa (swimmer's ear) and otomycosis","name_fa":"اوتیت خارجی (گوش شناگر) و اوتومایکوز","cc":["ent"],"keywords":"otitis externa, swimmer's ear, otomycosis, ofloxacin otic, acetic acid hydrocortisone, ciprofloxacin hydrocortisone, ear wick, اوتیت خارجی, گوش شناگر","status":"draft","features":["خارش، درد و حساسیت گوش خارجی؛ اریتم و ادم مجرای گوش، ترشح، کراست و کاهش شنوایی؛ درد با حرکت لاله و tragus؛ عوامل خطر: شنا، تروما، افزایش pH مجرا","شایع‌ترین ارگانیسم: Pseudomonas aeruginosa، Enterobacteriaceae و Proteus، S. aureus؛ otomycosis (قارچی): نواحی گرمسیر، نقص ایمنی یا پس از آنتی‌بیوتیک طولانی: Aspergillus و Candida"],"ddx":[{"n":"Malignant otitis externa |","cm":1},{"n":"Otitis media with perforation / mastoiditis / furuncle |"}],"redflags":["تب، گسترش پری‌آوریکولار، دیابت/نقص ایمنی (malignant OE)"],"guide":"ضددرد، تمیز کردن مجرا، عوامل اسیدی‌کننده، ضدمیکروب موضعی و گاه استروئید موضعی. تمیز کردن با شستشوی مجرا با hydrogen peroxide رقیق 1:1 با سالین یا آب گرم یا ساکشن ملایم. معمول 7 روز: ofloxacin otic 5 قطره دو بار روزانه؛ acetic acid/hydrocortisone otic 5 قطره سه بار روزانه (با سوراخ TM ممنوع)؛ ciprofloxacin/hydrocortisone otic 3 قطره دو بار روزانه. ادم قابل‌توجه: wick یا گاز در مجرا. آنتی‌بیوتیک خوراکی خط اول نیست مگر تب یا گسترش پری‌آوریکولار.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 151: Ear, Nose, and Sinus Emergencies, pp. 831–837"},"malignant-otitis-externa":{"id":"malignant-otitis-externa","variants":[{"id":"malignant-oe-main","o":{"I":[{"t":"CT temporal bone / skull base (extent and stage of disease)"}],"L":[{"t":"CBC, ESR / CRP, glucose, creatinine; culture of ear drainage"}],"A":[{"t":"Tobramycin 2 mg/kg IV AND piperacillin 3.375–4.5 g IV, or ceftriaxone 1 g IV, or ciprofloxacin 400 mg IV","fl":[{"k":"ci","v":"aminoglycoside — renal function / ototoxicity"}]}],"Co":[{"t":"Emergent ENT consultation; admit; glycemic control (endocrinology)"}]},"name":"Malignant otitis externa","level":"I","imp":"Malignant otitis externa","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مرد ۷۰ ساله دیابتی با درد شدید گوش و ترشح 3 هفته‌ای و فلج صورت.","why":"CT و آنتی‌بیوتیک ضد Pseudomonas IV."}],"ch":"151","name":"Malignant (necrotizing) otitis externa","name_fa":"اوتیت خارجی بدخیم (نکروزان)","cc":["ent","headache"],"keywords":"malignant otitis externa, necrotizing otitis externa, skull base osteomyelitis, Pseudomonas, diabetic, اوتیت خارجی بدخیم","status":"draft","features":["عفونت بالقوه تهدیدکننده حیات مجرای خارجی با گسترش متغیر به قاعده جمجمه (استئومیلیت)؛ تاریخی > 90% P. aeruginosa، اکنون 15% MRSA؛ سالمند، دیابتی و نقص ایمنی؛ شک بالا لازم؛ CT برای گسترش و مرحله"],"ddx":[{"n":"Otitis externa / skull base osteomyelitis / cranial neuropathy |","cm":1}],"redflags":["دیابت/سالمند با اوتالژی شدید ماندگار، گرانولاسیون مجرا، فلج عصب کرانیال"],"guide":"مشاوره اورژانس ENT: tobramycin 2 mg/kg IV و piperacillin 3.375 تا 4.5 g IV، یا ceftriaxone 1 g IV، یا ciprofloxacin 400 mg IV؛ بستری.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 151: Ear, Nose, and Sinus Emergencies, pp. 831–837"},"otitis-media":{"id":"otitis-media","variants":[{"id":"otitis-media-main","o":{"S":[{"t":"Analgesics for any degree of pain"}],"A":[{"t":"Amoxicillin 250–500 mg PO three times daily for 7–10 days; alternatives: azithromycin 500 mg PO day 1 then 250 mg daily × 4 days; cefuroxime 500 mg PO twice daily × 10 days"},{"t":"No response after 72 h: cefuroxime or amoxicillin/clavulanate; extend coverage to 3 weeks for OM with effusion","fl":[{"k":"ci","v":"penicillin allergy; renal dose adjust"}]}],"T":[{"t":"Pneumatic otoscopy; assess facial nerve"}],"Co":[{"t":"Follow-up with PCP for re-examination; emergent ENT if facial nerve paralysis or intracranial signs"}]},"name":"Acute otitis media (adult)","level":"III","imp":"Acute otitis media","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۳۰ ساله پس از سرماخوردگی با اوتالژی و تب خفیف؛ TM برجسته و قرمز.","why":"آموکسی‌سیلین و ضددرد."}],"ch":"151","name":"Acute otitis media (adult)","name_fa":"اوتیت میانی حاد (بزرگسال)","cc":["ent","fever"],"keywords":"otitis media, acute otitis media, amoxicillin, azithromycin, cefuroxime, tympanic membrane, otalgia, اوتیت میانی","status":"draft","features":["بروز و شیوع در سن پیش‌دبستانی اوج دارد؛ باکتری‌های حاد: S. pneumoniae، H. influenzae، M. catarrhalis؛ مزمن: S. aureus، P. aeruginosa، بی‌هوازی؛ اوتالژی با/بدون تب؛ کاهش شنوایی و اوتوره؛ TM قرمز یا زرد/سفید، کشیده یا برجسته و تحرک کم در otoscopy پنوماتیک؛ معاینه عصب صورت","عوارض: سوراخ TM، کاهش شنوایی هدایتی، لابیرنتیت سروز حاد، فلج صورت (ENT اورژانس)، ماستوئیدیت، ترومبوز سینوس لترال، کلستئاتوما و عوارض داخل‌جمجمه‌ای؛ سوراخ TM و کاهش شنوایی معمولاً خودمحدود"],"ddx":[{"n":"Mastoiditis / lateral sinus thrombosis |","cm":1},{"n":"Otitis externa / referred pain (dental, TMJ) / bullous myringitis |"}],"redflags":["فلج صورت، ورم پشت گوش، سردرد/ علائم عصبی، تب بالا"],"guide":"بزرگسال: amoxicillin 250 تا 500 mg PO سه بار روزانه × 7 تا 10 روز (10 روز)؛ جایگزین: azithromycin 500 mg PO روز اول سپس 250 mg روزانه × 4 روز یا cefuroxime 500 mg PO دو بار × 10 روز؛ عدم پاسخ پس از 72 ساعت: cefuroxime یا amoxicillin/clavulanate؛ با effusion: تا 3 هفته؛ ضددرد برای هر درجه درد؛ پیگیری PCP. کودکان: روش wait-and-see ممکن (در بزرگسال بررسی نشده).","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 151: Ear, Nose, and Sinus Emergencies, pp. 831–837"},"mastoiditis-lateral-sinus-thrombosis":{"id":"mastoiditis-lateral-sinus-thrombosis","variants":[{"id":"mastoiditis-main","o":{"I":[{"t":"CT temporal bone / head with contrast (extent of bony involvement; intracranial complications)"}],"L":[{"t":"CBC, CRP, blood cultures, electrolytes, creatinine"}],"A":[{"t":"Vancomycin 1–2 g IV or ceftriaxone 1 g IV","fl":[{"k":"hi","v":""}]}],"Co":[{"t":"Emergent ENT consultation (surgical drainage may be required); admit"}]},"name":"Acute mastoiditis","level":"I","imp":"Acute mastoiditis","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"کودک/بزرگسال با اوتیت میانی، تب، قرمزی و تورم پشت گوش و پیش‌آمدگی لاله.","why":"CT و آنتی‌بیوتیک IV؛ ENT."},{"id":"lateral-sinus-thrombosis-main","o":{"I":[{"t":"CT head with contrast; MRI / MR venography or angiography (more sensitive)"}],"L":[{"t":"CBC, coagulation, blood cultures, electrolytes"}],"A":[{"t":"Nafcillin 2 g IV plus ceftriaxone 1 g IV plus metronidazole 500 mg IV","fl":[{"k":"hi","v":""}]}],"Co":[{"t":"Emergent ENT consultation; admit; neurology / neurosurgery"}]},"name":"Lateral (sigmoid) sinus thrombosis","level":"I","imp":"Lateral sinus thrombosis (otogenic)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"بیمار با اوتیت مزمن، سردرد، پاپیلادم، دوبینی (فلج عصب 6) و ورتیگو.","why":"MRV/CT و آنتی‌بیوتیک سه‌گانه."}],"ch":"151","name":"Acute mastoiditis and lateral sinus thrombosis","name_fa":"ماستوئیدیت حاد و ترومبوز سینوس لترال","cc":["ent","headache","fever"],"keywords":"acute mastoiditis, postauricular swelling, lateral sinus thrombosis, sigmoid sinus thrombosis, vancomycin, ceftriaxone, nafcillin, metronidazole, ماستوئیدیت","status":"draft","features":["ماستوئیدیت حاد: گسترش عفونت گوش میانی به سلول‌های هوایی ماستوئید؛ اوتالژی، تب، اریتم/تورم/حساسیت پشت گوش؛ پیش‌آمدگی لاله با محو شدن چین پشت گوش؛ CT: گسترش درگیری استخوانی","ترومبوز سینوس لترال: گسترش عفونت/التهاب به سینوس لترال و سیگموئید؛ سردرد شایع؛ پاپیلادم، فلج عصب 6 و ورتیگو؛ CT؛ MRI یا آنژیوگرافی حساس‌تر"],"ddx":[{"n":"Meningitis / brain abscess / cerebral venous thrombosis |","cm":1},{"n":"Otitis externa / postauricular lymphadenitis |"}],"redflags":["ورم پشت گوش، پاپیلادم، فلج عصب 6، سردرد شدید، تب"],"guide":"ماستوئیدیت: مشاوره اورژانس ENT، vancomycin 1 تا 2 g IV یا ceftriaxone 1 g IV و بستری؛ ممکن جراحی تخلیه. ترومبوز سینوس لترال: مشاوره اورژانس ENT، ترکیب nafcillin 2 g IV + ceftriaxone 1 g IV + metronidazole 500 mg IV و بستری.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 151: Ear, Nose, and Sinus Emergencies, pp. 831–837"},"ear-trauma-foreign-body-cerumen-perforation":{"id":"ear-trauma-foreign-body-cerumen-perforation","variants":[{"id":"auricular-hematoma-burn","o":{"T":[{"t":"Immediate incision and drainage of auricular hematoma with compressive dressing (prevent reaccumulation)"},{"t":"Superficial burn / cold injury: cleaning, topical non-sulfa-containing antibiotic ointment, light dressing; frostbite: rapid rewarming with saline-soaked gauze at 38–40°C with analgesia"}],"A":[{"t":"Antibiotic coverage for P. aeruginosa and S. aureus in immunocompromised patients"}],"Co":[{"t":"ENT follow-up; immediate ENT / burn center consultation for second- or third-degree burn"}]},"name":"Auricular hematoma and thermal injury of the ear","level":"II","imp":"Auricular hematoma / ear thermal injury","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"کشتی‌گیر ۲۲ ساله با تورم قرمز-بنفش لاله پس از ضربه.","why":"تخلیه فوری و پانسمان فشاری برای پیشگیری از cauliflower ear."},{"id":"ear-foreign-body-cerumen","o":{"T":[{"t":"Foreign body: visualize (check TM perforation / infection); live insect — immobilize with 2% lidocaine solution in canal; remove with forceps, hooked probe or suction catheter; irrigation for small non-organic objects"},{"t":"Cerumen: scoop / loop; soften with half-strength hydrogen peroxide, sodium bicarbonate, mineral oil or carbamide peroxide otic; irrigate with body-temperature fluid via 18-gauge IV catheter / ear syringe directed at canal wall (not TM)","fl":[{"k":"ci","v":"no irrigation if TM perforation"}]}],"Co":[{"t":"ENT if foreign body with TM perforation or cannot be safely removed; asymptomatic cerumen: discharge with softening otic and follow-up"}]},"name":"Ear foreign body / cerumen impaction","level":"III","imp":"Ear foreign body / cerumen impaction","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"کودک ۵ ساله با مهره در گوش؛ یا مرد ۶۰ ساله با کاهش شنوایی و پر شدن گوش از سرومن.","why":"برداشتن؛ نرم کننده یا شستشو."},{"id":"tm-perforation-bullous-myringitis","o":{"S":[{"t":"Analgesics; warm compresses (bullous myringitis)"}],"A":[{"t":"No antibiotics for TM perforation unless persistent foreign material in canal / middle ear; antibiotics for concomitant OM (bullous myringitis)"}],"T":[{"t":"Keep water out of ear canal"}],"Co":[{"t":"Expedited specialty (ENT) referral for isolated blunt / noise trauma perforation; discharge"}]},"name":"TM perforation / bullous myringitis","level":"III","imp":"Tympanic membrane perforation / bullous myringitis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۳۰ ساله پس از ضربه به گوش با درد حاد، کاهش شنوایی و ترشح خونی خفیف.","why":"اغلب خودبه‌خود بهبود؛ از ورود آب به گوش جلوگیری."}],"ch":"151","name":"Ear trauma (hematoma, burns), foreign body, cerumen impaction, bullous myringitis, TM perforation","name_fa":"تروما، جسم خارجی، سرومن، میرینژیت بولوس و سوراخ پرده تمپان","cc":["ent","wound-bite"],"keywords":"auricular hematoma, cauliflower ear, ear foreign body, cerumen impaction, bullous myringitis, tympanic membrane perforation, گوش گل کلمی, سرومن, سوراخ پرده","status":"draft","features":["هماتوم لاله: از هر تروما؛ درمان نامناسب ← تحریک perichondrium و غضروف نامتقارن («cauliflower ear»)؛ برش و تخلیه فوری با پانسمان فشاری؛ آنتی‌بیوتیک برای P. aeruginosa و S. aureus در نقص ایمنی؛ آسیب حرارتی: گرما یا سرما: سطحی: تمیز کردن، پماد آنتی‌بیوتیک بدون سولفا و پانسمان سبک؛ frostbite: گرم کردن سریع با گاز آغشته سالین 38 تا 40°C؛ درجه 2 و 3: مشاوره فوری ENT یا مرکز سوختگی","جسم خارجی: معمولاً قابل مشاهده؛ شواهد عفونت یا سوراخ TM؛ حشره زنده با lidocaine 2% در مجرا بی‌حرکت شود؛ برداشتن با فورسپس، قلاب یا کاتتر ساکشن؛ شستشو برای اجسام کوچک (مواد آلی متورم می‌شوند)؛ ENT اگر سوراخ TM یا برداشتن ناامن","سرومن: کاهش شنوایی، فشار، سرگیجه، وزوز و اوتالژی؛ پنبه‌گوش‌پاک‌کن؛ scoop/loop؛ نرم کننده: hydrogen peroxide نیم‌قدرت، sodium bicarbonate، روغن معدنی یا carbamide peroxide؛ شستشو با مایع دمای بدن با IV کاتتر 18G یا سرنگ گوش به سمت دیواره مجرا نه TM؛ بدون علامت: ترخیص با نرم کننده و پیگیری","bullous myringitis: بول روی TM و مجرای عمقی، دردناک؛ ویروس، Mycoplasma، Chlamydia psittaci؛ تشخیص بالینی؛ ضددرد و کمپرس گرم؛ آنتی‌بیوتیک در OM همزمان","سوراخ TM: عفونت میانی، بارو‌تروما، تروما بلانت/نافذ/صوتی، نادراً صاعقه؛ درد حاد و کاهش شنوایی ± اوتوره خونی؛ ورتیگو و وزوز گذرا؛ بیشتر خودبه‌خود بهبود: بدون آنتی‌بیوتیک مگر مواد خارجی باقی‌مانده؛ ترخیص با ارجاع تخصصی سریع؛ آب وارد گوش نشود"],"ddx":[{"n":"Basilar skull fracture / inner ear injury |","cm":1},{"n":"Otitis externa / otitis media |"}],"redflags":["هماتوم لاله، سوراخ TM با ورتیگو/فلج صورت، جسم خارجی غیرقابل برداشتن"],"guide":"مطابق ویژگی‌های بالا؛ ENT برای سوراخ TM همراه جسم خارجی یا جسم غیرقابل برداشتن.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 151: Ear, Nose, and Sinus Emergencies, pp. 831–837"},"tinnitus-sudden-hearing-loss":{"id":"tinnitus-sudden-hearing-loss","variants":[{"id":"tinnitus-hearing-loss-main","o":{"L":[{"t":"(glucose, CBC, ESR as indicated; audiometry via ENT); review ototoxic medications"}],"T":[{"t":"Stop potentially offending drugs (aspirin, NSAIDs, aminoglycosides, loop diuretics, chemotherapeutics) if condition allows"}],"Co":[{"t":"Otolaryngology consultation (sudden hearing loss; poor prognostic: severe loss and vertigo)"}]},"name":"Tinnitus / sudden hearing loss","level":"III","imp":"Tinnitus / sudden hearing loss","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۵۰ ساله با کاهش ناگهانی شنوایی گوش راست و وزوز از صبح.","why":"ارجاع ENT؛ داروهای اتوتوکسیک را قطع کن."}],"ch":"151","name":"Tinnitus and sudden hearing loss","name_fa":"وزوز گوش و کاهش ناگهانی شنوایی","cc":["ent","dizziness-vertigo"],"keywords":"tinnitus, sudden sensorineural hearing loss, ototoxic, acoustic neuroma, Cogan syndrome, وزوز, کم شنوایی ناگهانی","status":"draft","features":["وزوز: ادراک صدا بدون محرک خارجی؛ ثابت یا ضربان‌دار؛ عینی (توسط معاینه‌کننده شنیده می‌شود) و ذهنی (شایع‌تر)؛ علل: عروقی، مکانیکی، عصبی، Ménière و غیره؛ داروها: aspirin، NSAID، aminoglycoside، دیورتیک لوپ، شیمی‌درمانی","کم‌شنوایی ناگهانی: ایدیوپاتیک (شایع‌ترین)، عفونی، عروقی/خونی، متابولیک، روماتولوژیک، هدایتی؛ Ménière، Cogan، نوروم آکوستیک، پارگی حلزون، داروهای اتوتوکسیک؛ پیش‌آگهی بد: کم‌شنوایی شدید در ارائه و ورتیگو"],"ddx":[{"n":"Stroke (AICA) / acoustic neuroma |","cm":1},{"n":"Ménière disease / ototoxic medication / cochlear rupture |"}],"redflags":["کاهش شنوایی ناگهانی، ورتیگو همراه، علائم عصبی"],"guide":"در صورت امکان داروی مسبب قطع شود؛ تشخیص دقیق معمولاً ارجاع ENT می‌خواهد؛ اگر علت با شرح حال و معاینه مشخص نشد مشاوره ENT.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 151: Ear, Nose, and Sinus Emergencies, pp. 831–837"},"epistaxis":{"id":"epistaxis","variants":[{"id":"epistaxis-anterior","o":{"L":[{"t":"(CBC / PT-INR / aPTT if anticoagulant use, bleeding diathesis or significant blood loss)"}],"S":[{"t":"Oxymetazoline 0.05% two sprays per nostril (or phenylephrine 0.25% two sprays) after blowing nose to clear clots","fl":[{"k":"ci","v":"avoid in uncontrolled hypertension"}]},{"t":"Pledget soaked with 1:1 mixture of 4% lidocaine and 0.05% oxymetazoline for anesthesia / hemostasis"}],"T":[{"t":"Direct external pressure on cartilage just distal to nasal bones for 15 min leaning forward; reexamine; repeat once"},{"t":"Silver nitrate chemical cautery (roll applicator on bleeding site until silvery-black; avoid bilateral septal cautery); if no source: anterior packing (thrombogenic foam / gel, commercial device, dehydrated sponge or gauze, or inflatable balloon); topical tranexamic acid 500 mg via cotton pledget as alternative"},{"t":"Nasal pack: remove nonabsorbable pack in 2–3 days (ENT)"}],"A":[{"t":"Amoxicillin/clavulanate 500/125 mg PO three times daily for all patients with nasal packs","fl":[{"k":"ci","v":"penicillin allergy"}]}],"Co":[{"t":"ENT if packing or cautery fails; follow-up for pack removal"}]},"name":"Anterior epistaxis (pressure, cautery, packing)","level":"II","imp":"Epistaxis, anterior","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۴۵ ساله با خونریزی از سوراخ چپ بینی بدون ضدانعقاد؛ منبع قدامی دیده می‌شود.","why":"فشار، vasoconstrictor، cautery یا packing."},{"id":"epistaxis-posterior","o":{"L":[{"t":"CBC, PT/INR, aPTT, type and screen, electrolytes, creatinine"}],"S":[{"t":"Oxymetazoline 0.05% / phenylephrine 0.25% sprays; IV crystalloid / blood products as needed for hemodynamic compromise","fl":[{"k":"ci","v":"caution in heart failure"}]},{"t":"Correct coagulopathy as indicated (e.g., vitamin K / PCC if warfarin-related major bleed)","fl":[{"k":"note","v":"BP treatment generally not advised except with ENT"}]}],"T":[{"t":"Posterior dehydrated sponge pack or inflatable balloon tamponade device (independently inflatable anterior and posterior balloons); pack removal 2–3 days"},{"t":"Continuous monitoring; watch for vasovagal syncope, pack dislodgement, toxic shock syndrome, sinusitis"}],"A":[{"t":"Amoxicillin/clavulanate 500/125 mg PO three times daily (prophylaxis with nasal pack)"}],"Co":[{"t":"ENT consultation for all posterior packs (possible hospital admission); hematology if coagulopathy"}]},"name":"Posterior epistaxis (posterior pack / balloon)","level":"I","imp":"Epistaxis, posterior","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"none","sc":"مرد ۷۰ ساله مصرف‌کننده warfarin با خونریزی شدید از هر دو سوراخ و خون در حلق؛ فشار 100/60.","why":"پک خلفی/بالون و تصحیح انعقاد؛ ENT و بستری."}],"ch":"151","name":"Epistaxis (anterior and posterior)","name_fa":"خونریزی بینی (قدامی و خلفی)","cc":["bleeding-bruising","ent"],"keywords":"epistaxis, nosebleed, anterior epistaxis, posterior epistaxis, silver nitrate cautery, nasal packing, tranexamic acid, oxymetazoline, خونریزی بینی","status":"draft","features":["قدامی یا خلفی؛ خلفی: منبع قدامی دیده نشود، خونریزی از هر دو سوراخ یا خون در حلق خلفی پس از کنترل قدامی","شرح حال سریع: مدت و شدت و عوامل (تروما، ضدانعقاد، عفونت، اختلال خونریزی)"],"ddx":[{"n":"Posterior epistaxis / coagulopathy |","cm":1},{"n":"Nasal tumor / trauma / hereditary hemorrhagic telangiectasia |"}],"redflags":["ضدانعقاد/اختلال خونریزی، خونریزی خلفی، ناپایداری همودینامیک"],"guide":"1) شرح حال سریع. 2) فین کردن برای خارج کردن لخته؛ oxymetazoline 0.05% دو اسپری هر سوراخ یا phenylephrine 0.25% دو اسپری. 3) بازرسی خونریزی قدامی با نور خوب، اسپکولوم و کاتتر ساکشن. 4) فشار مستقیم خارجی روی غضروف دیستال استخوان‌های بینی به مدت 15 دقیقه با خم شدن به جلو؛ بازمعاینه؛ یک تکرار. 5) ادامه خونریزی: منبع قدامی دیده شود ← cautery شیمیایی؛ منبع نامشخص ← packing. 6) cautery با silver nitrate استاندارد ED: پنبه یا pledget آغشته به مخلوط 1:1 از lidocaine 4% و oxymetazoline 0.05% با فورسپس bayonet؛ پس از هموستاز نوک اپلیکاتور silver nitrate با فشار روی ناحیه تا نقره‌ای-سیاه؛ ناحیه کوچک اطراف؛ پرهیز از cautery بیش‌ازحد و دوطرفه septal (سوراخ septum). 7) packing قدامی: فوم/ژل ترومبوژنیک، دستگاه تجاری یا گاز؛ اسفنج‌های بینی dehydrated (طول‌های مختلف)؛ پماد آنتی‌بیوتیک و سریع در کف حفره؛ با خون منبسط می‌شود (یا آب استریل)؛ اسفنج بلند فقط خلفی (عارضه)؛ بالون تامپوناد قابل‌باد شدن (قدامی و/یا خلفی) راحت‌تر؛ فوم و ژل جذب‌شدنی بدون نیاز به برداشتن؛ پک غیرجذبی: برداشتن توسط ENT طی 2 تا 3 روز؛ tranexamic acid 5 mL (500 mg) روی مخاط با pledget پنبه 15 cm؛ شکست: ENT. 8) خلفی: اسفنج خلفی dehydrated یا بالون (بالون قدامی و خلفی مستقل)؛ همه پک خلفی نیاز به ENT برای احتمال بستری؛ برداشتن 2 تا 3 روز. 9) همه پک بینی: آنتی‌بیوتیک پروفیلاکسی amoxicillin/clavulanate 500/125 mg PO سه بار روزانه. عوارض: سنکوپ واگال، جابه‌جایی پک، خونریزی مجدد، سینوزیت، TSS. درمان فشار بالا معمولاً توصیه نمی‌شود مگر با ENT.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 151: Ear, Nose, and Sinus Emergencies, pp. 831–837"},"nasal-fracture-septal-hematoma-fb":{"id":"nasal-fracture-septal-hematoma-fb","variants":[{"id":"nasal-fracture-main","o":{"I":[{"t":"Radiographs usually unnecessary; CT if cribriform plate / facial fracture / CSF rhinorrhea suspected"}],"S":[{"t":"Intermittent ice; analgesics (acetaminophen); over-the-counter decongestants"}],"T":[{"t":"Examine septum with speculum and good light for septal hematoma; observe for CSF rhinorrhea (may be delayed weeks)"}],"Co":[{"t":"ENT follow-up in 6–10 days for re-examination and possible reduction; immediate neurosurgery consult if cribriform plate injury suspected"}]},"name":"Nasal fracture","level":"III","imp":"Nasal fracture","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۲۲ ساله پس از مشت به بینی با بدشکلی، تورم و اکیموز؛ بدون ترشح شفاف.","why":"تشخیص بالینی؛ هماتوم سپتوم و CSF leak را رد کن."},{"id":"nasal-septal-hematoma","o":{"T":[{"t":"Sniffing position; speculum; 4% lidocaine pledgets (or lidocaine without epinephrine infiltration); horizontal mucosal incision avoiding cartilage; evacuate hematoma; bilateral anterior packing coated with antibiotic ointment"}],"A":[{"t":"Amoxicillin/clavulanate 500/125 mg PO three times daily if packing > 24 h"}],"Co":[{"t":"ENT follow-up"}]},"name":"Nasal septal hematoma (drainage)","level":"I","imp":"Nasal septal hematoma","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"کودک ۱۲ ساله پس از ضربه به بینی با انسداد دوطرفه و برجستگی نرم قرمز-آبی سپتوم.","why":"تخلیه فوری برای پیشگیری از نکروز سپتوم."},{"id":"nasal-foreign-body","o":{"S":[{"t":"Oxymetazoline 0.05% topical vasoconstriction ± 4% nebulized lidocaine"}],"T":[{"t":"Remove under direct visualization with forceps, suction catheter, hooked probe or balloon-tipped catheter"}],"Co":[{"t":"ENT if removal unsuccessful"}]},"name":"Nasal foreign body","level":"III","imp":"Nasal foreign body","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"کودک ۳ ساله با ترشح بدبو یک‌طرفه بینی.","why":"vasoconstriction و برداشتن با دید."}],"ch":"151","name":"Nasal fracture, septal hematoma and nasal foreign body","name_fa":"شکستگی بینی، هماتوم سپتوم و جسم خارجی بینی","cc":["head-injury","ent"],"keywords":"nasal fracture, septal hematoma, cribriform plate, CSF rhinorrhea, nasal foreign body, شکستگی بینی, هماتوم سپتوم","status":"draft","features":["شکستگی بینی: تشخیص بالینی: مکانیسم، تورم، حساسیت، crepitus، بدشکلی و اکیموز دور چشم؛ رادیوگرافی معمولاً لازم نیست؛ یخ متناوب، ضددرد و ضداحتقان؛ پیگیری ENT 6 تا 10 روز؛ شکستگی cribriform plate ← CSF rhinorrhea (ممکن هفته‌ها تأخیر) ← CT و نوروسرجری فوری","هماتوم سپتوم: هر تروما به بینی؛ لیفت perichondrium از غضروف و قطع خون‌رسانی؛ باید تخلیه شود تا نکروز ایسکمیک سپتوم نشود؛ اسپکولوم و نور خوب و لمس سپتوم","جسم خارجی بینی: انسداد یک‌طرفه، ترشح بدبو یا اپیستاکسی یک‌طرفه مداوم؛ vasoconstriction با oxymetazoline 0.05% و احتمالاً lidocaine 4% نبولایز؛ برداشتن با دید مستقیم: فورسپس، ساکشن، قلاب یا کاتتر بالن‌دار؛ ENT اگر ناموفق"],"ddx":[{"n":"Septal hematoma / cribriform plate fracture (CSF leak) |","cm":1},{"n":"Facial / orbital fracture |"}],"redflags":["هماتوم سپتوم، CSF rhinorrhea، علائم عصبی"],"guide":"هماتوم سپتوم تخلیه: 1) وضعیت sniffing و اسپکولوم؛ ساکشن، شستشو و پک آماده. 2) pledget آغشته به lidocaine 4%؛ تزریق lidocaine بدون اپی‌نفرین در صورت نیاز. 3) برش افقی مخاط (غضروف را نبُر). 4) خروج هماتوم. 5) پک قدامی دوطرفه آغشته به پماد آنتی‌بیوتیک. 6) پروفیلاکسی amoxicillin/clavulanate 500/125 mg PO سه بار روزانه اگر پک > 24 ساعت. 7) پیگیری ENT.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 151: Ear, Nose, and Sinus Emergencies, pp. 831–837"},"rhinosinusitis":{"id":"rhinosinusitis","variants":[{"id":"sinusitis-uncomplicated","o":{"S":[{"t":"Nasal saline irrigation; oxymetazoline 0.05% two sprays per nostril twice daily or phenylephrine 0.25% two sprays per nostril four times daily (≤ 3 days)","fl":[{"k":"ci","v":"uncontrolled hypertension; rebound congestion"}]},{"t":"Analgesics / antipyretics"}],"A":[{"t":"Only if purulent secretions and severe symptoms > 10 days: amoxicillin 500 mg PO three times daily (10 days); penicillin allergic: TMP-SMX 160/800 mg twice daily or erythromycin 250–500 mg twice daily; antibiotic in prior 6 weeks: levofloxacin 500 mg daily","fl":[{"k":"ci","v":"fluoroquinolone — QT / tendinopathy"}]}],"Co":[{"t":"PCP / ENT follow-up if recurrent or chronic (culture and sinus CT outpatient)"}]},"name":"Acute uncomplicated rhinosinusitis","level":"III","imp":"Acute rhinosinusitis, uncomplicated","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۳۰ ساله با گرفتگی بینی، فشار صورت و ترشح چرکی 4 روز.","why":"شستشو و ضداحتقان؛ آنتی‌بیوتیک فقط بعد از 10 روز یا شدید."},{"id":"sinusitis-complicated","o":{"I":[{"t":"CT sinuses / orbit / head with contrast (toxic patients, suspected intracranial extension); MRI if cavernous sinus thrombosis suspected"}],"L":[{"t":"CBC, CRP, blood cultures, electrolytes, creatinine; lumbar puncture only after imaging if meningitis suspected"}],"A":[{"t":"IV broad-spectrum antibiotics covering sinus pathogens / MRSA as indicated (e.g., ceftriaxone + vancomycin ± metronidazole; adapt per local protocol)"}],"Co":[{"t":"Emergent ENT / ophthalmology / neurosurgery as indicated; admit"}]},"name":"Sinusitis with suspected complications (orbital / intracranial)","level":"I","imp":"Sinusitis with orbital / intracranial complication","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مرد ۲۰ ساله با سینوزیت، تب بالا، تورم اطراف چشم، دوبینی و سردرد شدید.","why":"CT/MRI و آنتی‌بیوتیک IV؛ ENT/چشم/نوروسرجری."}],"ch":"151","name":"Sinusitis and rhinosinusitis","name_fa":"سینوزیت و رینوسینوزیت","cc":["ent","headache","fever"],"keywords":"sinusitis, rhinosinusitis, nasal irrigation, oxymetazoline, amoxicillin, levofloxacin, sinus CT, complications, سینوزیت","status":"draft","features":["التهاب مخاط سینوس‌های پارانازال (ماگزیلاری، فرونتال، اتموئید)؛ رینوسینوزیت: درگیری حفره بینی و رینیت؛ حاد، تحت‌حاد و مزمن","علائم: گرفتگی بینی، درد/فشار صورت، hyposmia، ترشح بینی، درد دندان، تب و فشار سینوس با حرکت سر/بدن؛ درد و حساسیت با پرکاشن، تورم مخاط، تورم و قرمزی صورت","عوارض: منژیت، ترومبوز سینوس کاورنو، آبسه و empyema داخل‌جمجمه‌ای، سلولیت اربیت، استئومیلیت؛ بیمار سمی یا علائم عصبی کانونی","تشخیص بالینی در رینوسینوزیت حاد بدون عارضه؛ تصویربرداری لازم نیست؛ CT در بیمار سمی و گسترش داخل‌جمجمه‌ای؛ مزمن یا راجعه: کشت و CT سینوس ترجیحاً سرپایی"],"ddx":[{"n":"Orbital cellulitis / meningitis / cavernous sinus thrombosis |","cm":1},{"n":"Dental infection / migraine / allergic rhinitis |"}],"redflags":["تورم اطراف چشم، تغییر بینایی، سردرد شدید، سفتی گردن، علائم عصبی"],"guide":"حمایتی در حاد بدون عارضه: شستشوی بینی با/بدون ضداحتقان: oxymetazoline 0.05% دو اسپری هر سوراخ دو بار روزانه یا phenylephrine 0.25% دو اسپری چهار بار روزانه؛ ضداحتقان ≤ 3 روز. آنتی‌بیوتیک خوراکی برای ترشح چرکی و علائم شدید بیش از 10 روز: رژیم 10 روزه: amoxicillin 500 mg PO سه بار روزانه (خط اول)؛ TMP-SMX 160/800 mg دو بار یا erythromycin 250 تا 500 mg دو بار (آلرژی پنی‌سیلین)؛ levofloxacin 500 mg روزانه (آنتی‌بیوتیک در 6 هفته قبل).","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 151: Ear, Nose, and Sinus Emergencies, pp. 831–837"},"teething-pericoronitis":{"id":"teething-pericoronitis","variants":[{"id":"teething-main","o":{"S":[{"t":"Acetaminophen 15 mg/kg PO every 6 h"}],"T":[{"t":"Frozen damp towel to suck on; topical anesthetics with great caution in young infants (depress gag reflex)"}],"Co":[{"t":"Discharge; PCP follow-up"}]},"name":"Teething (infant)","level":"III","imp":"Tooth eruption (teething)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"شیرخوار ۸ ماهه با تحریک‌پذیری و آب‌ریزش دهان، بدون تب و اسهال.","why":"علامتی؛ علل تب/اسهال را رد کن."},{"id":"pericoronitis-main","o":{"S":[{"t":"Ibuprofen 400–800 mg PO three times daily (± hydrocodone 5 mg/acetaminophen 325 mg 1–2 tablets PO four times daily)","fl":[{"k":"ci","v":"NSAID — renal disease, GI bleeding"}]}],"A":[{"t":"Penicillin VK 500 mg PO four times daily, or clindamycin 300 mg PO four times daily"}],"T":[{"t":"Warm saline mouth rinses"}],"Co":[{"t":"Referral to oral surgeon / dentist for third molar extraction"}]},"name":"Pericoronitis (third molar eruption)","level":"III","imp":"Pericoronitis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۲۲ ساله با درد و تورم لثه اطراف مولار سوم پایین.","why":"آنتی‌بیوتیک و ضددرد؛ ارجاع برای کشیدن."}],"ch":"152","name":"Tooth eruption (teething) and pericoronitis","name_fa":"درآوردن دندان (teething) و پریکورونیت","cc":["ent"],"keywords":"teething, pericoronitis, wisdom teeth, third molar, penicillin VK, clindamycin, ibuprofen, دندان درآوردن, دندان عقل","status":"draft","features":["teething: درآوردن دندان شیری: درد، تحریک‌پذیری و آب‌ریزش دهان؛ تب و اسهال نه ← علل دیگر را رد کن","پریکورونیت: بزرگسال و نوجوان: درد و التهاب موضعی با رویش مولار سوم («دندان عقل»)"],"ddx":[{"n":"Odontogenic infection / deep space infection |","cm":1},{"n":"Viral gingivostomatitis (fever) |"}],"redflags":["تب یا اسهال در کودک (علت دیگر)، تریسموس، تورم صورت"],"guide":"teething: حوله مرطوب منجمد برای مکیدن و acetaminophen 15 mg/kg PO هر 6 ساعت؛ بی‌حس‌کننده موضعی با احتیاط شدید در شیرخوار (کاهش رفلکس gag). پریکورونیت: penicillin VK 500 mg PO چهار بار روزانه یا clindamycin 300 mg PO چهار بار روزانه، ibuprofen 400 تا 800 mg PO سه بار روزانه (± hydrocodone 5 mg/acetaminophen 325 mg یک تا دو قرص چهار بار روزانه)، و دهان‌شویه سالین گرم؛ ارجاع به جراح دهان یا دندانپزشک برای کشیدن مولار سوم.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 152: Oral and Dental Emergencies, pp. 838–844"},"dental-caries-pulpitis-periodontal":{"id":"dental-caries-pulpitis-periodontal","variants":[{"id":"dental-pain-pulpitis","o":{"S":[{"t":"Ibuprofen 400–800 mg PO three times daily; hydrocodone 5 mg/acetaminophen 325 mg 1–2 tablets PO four times daily if needed","fl":[{"k":"ci","v":"NSAID — renal disease / GI bleeding"}]},{"t":"Dental nerve block for short-term pain relief (e.g., bupivacaine)"}],"A":[{"t":"Penicillin VK 500 mg PO four times daily or clindamycin 300 mg PO four times daily (commonly prescribed; efficacy controversial); if abscess present consider antibiotics and incision and drainage"}],"T":[{"t":"Warm saline mouth rinses; percuss teeth with metallic object to localize"}],"Co":[{"t":"Dentist referral for definitive management"}]},"name":"Dental caries / pulpitis (toothache)","level":"III","imp":"Dental caries / pulpitis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۳۵ ساله با دندان‌درد شدید با سرما و گرما؛ دندان پوسیده؛ بدون تورم صورت.","why":"ضددرد، بلوک دندانی و ارجاع دندانپزشک."},{"id":"periodontal-abscess-anug","o":{"A":[{"t":"ANUG: metronidazole 500 mg PO three times daily","fl":[{"k":"ci","v":"alcohol interaction"}]},{"t":"Periodontal abscess (small): penicillin VK 500 mg PO four times daily or clindamycin 300 mg PO four times daily; larger abscesses: incision and drainage"},{"t":"Peri-implantitis: metronidazole 500 mg PO three times daily or amoxicillin 500 mg PO three times daily for 10 days"}],"T":[{"t":"Chlorhexidine 0.12% mouth rinses twice daily (irrigate around implant); analgesics; ANUG: protein-rich soft diet, multivitamins, oral fluids"}],"Co":[{"t":"Prompt dental referral (debridement / scaling / workup of predisposing factors such as HIV)"}]},"name":"Periodontal abscess / ANUG / peri-implantitis","level":"III","imp":"Periodontal abscess / ANUG / peri-implantitis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۲۵ ساله سیگاری و استرس‌دار با درد لثه، پاپیل‌های زخمی، بوی تعفنی و خونریزی لثه.","why":"metronidazole و chlorhexidine؛ ارجاع برای debridement."}],"ch":"152","name":"Dental caries, pulpitis, periodontal abscess, ANUG and peri-implantitis","name_fa":"پوسیدگی دندان، پولپیت، آبسه پریودنتال، ANUG و peri-implantitis","cc":["ent"],"keywords":"dental caries, pulpitis, toothache, periodontal abscess, ANUG, trench mouth, peri-implantitis, dental block, chlorhexidine, دندان درد, پولپیت, آبسه لثه","status":"draft","features":["caries: اسید باکتریایی ← فرسایش مینا؛ معاینه: دندان پوسیده؛ گاه نامرئی: کوبیدن دندان‌ها با ابزار فلزی؛ درمان‌نشده: پولپیت؛ برگشت‌پذیر: درد ناگهانی گذرا ثانیه‌ای با سرما/گرما؛ برگشت‌ناپذیر: درد دقیقه تا ساعت","آبسه پریودنتال: تجمع پلاک/آوار بین دندان و لثه","ANUG («trench mouth»): درد، پاپیلاهای بین‌دندانی زخمی «punched out»، خونریزی لثه، طعم بد، لنفادنوپاتی، تب و بوی تعفنی؛ جوانان با مقاومت کم (HIV، استرس، سوءتغذیه، مواد، عفونت)","peri-implantitis: عفونت ایمپلنت دندانی مشابه آبسه پریودنتال"],"ddx":[{"n":"Deep space infection / Ludwig angina / abscess |","cm":1},{"n":"Trigeminal neuralgia / sinusitis / TMJ / ACS (referred) |"}],"redflags":["تب، تورم صورت/گردن، trismus، مشکل بلع"],"guide":"pulpitis: آنتی‌بیوتیک (penicillin VK 500 mg PO چهار بار روزانه یا clindamycin 300 mg چهار بار) رایج ولی اثربخشی بحث‌برانگیز؛ درمان: ibuprofen 400 تا 800 mg PO سه بار روزانه، hydrocodone 5/acetaminophen 325 یک تا دو قرص چهار بار روزانه، دهان‌شویه سالین گرم؛ بلوک دندانی برای تسکین کوتاه‌مدت؛ ارجاع دندانپزشک؛ آبسه: آنتی‌بیوتیک و I&D. آبسه پریودنتال کوچک: penicillin VK یا clindamycin، ضددرد، دهان‌شویه chlorhexidine 0.12% دو بار روزانه؛ بزرگ: I&D؛ ارجاع سریع دندانپزشکی. ANUG: metronidazole 500 mg PO سه بار روزانه و chlorhexidine 0.12% دو بار روزانه + رژیم نرم پروتئین‌دار، مولتی‌ویتامین و مایعات؛ بهبود چشمگیر ظرف 24 ساعت؛ ارجاع برای debridement/scaling و ورک‌آپ عوامل مستعد. peri-implantitis: شستشوی اطراف ایمپلنت با chlorhexidine 0.12%، metronidazole 500 mg PO سه بار روزانه یا amoxicillin 500 mg PO سه بار روزانه × 10 روز، ضددرد و ارجاع دندانپزشک.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 152: Oral and Dental Emergencies, pp. 838–844"},"odontogenic-deep-space-infection":{"id":"odontogenic-deep-space-infection","variants":[{"id":"deep-space-infection-main","o":{"I":[{"t":"Contrast-enhanced CT neck / face (extent; airway) once airway secure; CXR PA (mediastinitis)"}],"L":[{"t":"CBC, CRP, electrolytes, creatinine, glucose, blood cultures, lactate"}],"A":[{"t":"Intravenous antibiotics (e.g., ampicillin-sulbactam 1.5–3 g IV every 6 h, or clindamycin 600 mg IV every 8 h, or penicillin G 2–3 million units IV every 6 h plus metronidazole 500 mg IV every 8 h; vancomycin if MRSA)","fl":[{"k":"hi","v":""}]}],"T":[{"t":"Early airway assessment / securement (fiberoptic or awake intubation / surgical airway backup); head up; NPO"},{"t":"Cavernous sinus thrombosis: add anticoagulation (with neurosurgery / ENT guidance)"}],"Co":[{"t":"Emergent oral and maxillofacial / ENT surgery consultation; ICU admission"}]},"name":"Ludwig's angina / odontogenic deep neck infection / cavernous sinus thrombosis","level":"I","imp":"Odontogenic deep space infection (Ludwig angina / cavernous sinus thrombosis)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"PA","sc":"مرد ۴۵ ساله با دندان آبسه‌دار، تورم زیرفکی دوطرفه، ریزش بزاق، trismus و تب 39.","why":"محافظت راه هوایی، آنتی‌بیوتیک IV و جراحی فوری."}],"ch":"152","name":"Odontogenic deep space infection (Ludwig's angina, cavernous sinus thrombosis)","name_fa":"عفونت فضای عمیق دندانی (Ludwig، ترومبوز سینوس کاورنو)","cc":["ent","fever"],"keywords":"Ludwig angina, deep space infection, cavernous sinus thrombosis, odontogenic infection, airway, submandibular space, آنژین لودویگ, عفونت فضای عمیق","status":"draft","features":["عفونت دندانی به‌راحتی به فضاهای صورت گسترش می‌یابد؛ همیشه درگیری فضای عمیق را رد کن؛ Ludwig: سلولیت هر دو فضای زیرفکی و زیرزبانی با گسترش به گردن و مدیاستن ← تهدید راه هوایی، عفونت شدید و مرگ؛ فضای infraorbital ← ترومبوز سینوس کاورنو: محدودیت نگاه جانبی، علائم مننژیال، سپسیس و کما"],"ddx":[{"n":"Retropharyngeal abscess / epiglottitis / angioedema |","cm":1},{"n":"Masticator space abscess / parotitis |"}],"redflags":["تورم کف دهان، trismus، تغییر صدا، ریزش بزاق، فلج عصب کرانیال"],"guide":"هر دو: آنتی‌بیوتیک IV و مشاوره اورژانس جراحی؛ ترومبوز سینوس کاورنو: افزودن ضدانعقاد؛ مراقبت زودهنگام راه هوایی.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 152: Oral and Dental Emergencies, pp. 838–844"},"postextraction-pain-dry-socket-bleeding":{"id":"postextraction-pain-dry-socket-bleeding","variants":[{"id":"dry-socket-main","o":{"S":[{"t":"Analgesics (NSAIDs / opioid as needed)"}],"A":[{"t":"Severe cases: penicillin VK 500 mg PO four times daily or clindamycin 300 mg PO four times daily"}],"T":[{"t":"Gentle irrigation of socket with saline or 0.12% chlorhexidine; pack socket with eugenol-impregnated gauze (change daily); chlorhexidine 0.12% mouth rinses twice daily; avoid smoking / straws"}],"Co":[{"t":"Dental follow-up in 24 hours"}]},"name":"Dry socket (alveolar osteitis)","level":"III","imp":"Dry socket (postextraction alveolar osteitis)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۳۰ ساله 3 روز پس از کشیدن مولار با درد شدید و طعم بد؛ سیگاری.","why":"شستشو و پک eugenol."},{"id":"postextraction-bleeding-main","o":{"L":[{"t":"Screening coagulation profile if measures fail (PT/INR, aPTT, platelet count)"}],"S":[{"t":"Local infiltration 1% lidocaine with epinephrine"}],"T":[{"t":"Bite on gauze over site for 20 min; pack socket with Gelfoam, Avitene or Surgicel (loosely approximating sutures to hold); careful silver nitrate application"}],"Co":[{"t":"Oral surgeon consultation if measures fail"}]},"name":"Postextraction bleeding","level":"II","imp":"Postextraction bleeding","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۵۵ ساله 6 ساعت پس از کشیدن دندان با خونریزی مداوم؛ بدون ضدانعقاد.","why":"گاز، پک موضعی و در شکست انعقاد."}],"ch":"152","name":"Postextraction pain, dry socket (alveolar osteitis) and postextraction bleeding","name_fa":"درد پس از کشیدن دندان، خشک شدن حفره (dry socket) و خونریزی پس از کشیدن","cc":["ent","bleeding-bruising"],"keywords":"dry socket, alveolar osteitis, postextraction bleeding, eugenol, chlorhexidine, Gelfoam, Surgicel, کشیدن دندان, خشک شدن حفره","status":"draft","features":["درد 24 تا 48 ساعت پس از کشیدن به یخ، بالا بردن سر و ضددرد پاسخ می‌دهد؛ dry socket 48 تا 72 ساعت پس از عمل با جابه‌جایی لخته: درد شدید، بوی بد و طعم بد؛ ارتباط با سیگار، نوشابه گازدار و استفاده از نی","خونریزی پس از کشیدن: از بیمار بخواهید 20 دقیقه گاز را گاز بگیرد؛ ادامه: پک حفره با Gelfoam، Avitene یا Surgicel؛ بخیه شل برای نگه داشتن؛ تزریق موضعی lidocaine 1% با epinephrine یا silver nitrate؛ شکست: پروفایل انعقادی و مشاوره جراح دهان"],"ddx":[{"n":"Coagulopathy / anticoagulant effect |","cm":1},{"n":"Osteomyelitis / abscess |"}],"redflags":["خونریزی غیرقابل کنترل، ضدانعقاد، علائم سیستمیک"],"guide":"dry socket: شستشوی ملایم حفره با سالین یا chlorhexidine 0.12% سپس پک گاز آغشته به eugenol؛ موارد شدید: penicillin VK 500 mg چهار بار یا clindamycin 300 mg چهار بار؛ ضددرد، تعویض روزانه پک، دهان‌شویه chlorhexidine 0.12% دو بار و پیگیری دندانپزشکی 24 ساعت.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 152: Oral and Dental Emergencies, pp. 838–844"},"aphthous-stomatitis-oral-cancer":{"id":"aphthous-stomatitis-oral-cancer","variants":[{"id":"aphthous-main","o":{"S":[{"t":"Triamcinolone acetonide 0.1% dental paste (Kenalog in Orabase) applied to lesions two to three times daily, or chlorhexidine 0.12% applied topically twice daily"}],"T":[{"t":"Analgesia; avoid spicy / acidic foods"}],"Co":[{"t":"Refer any suspicious lesion or lesion persisting > 14 days despite treatment to oral surgeon for biopsy"}]},"name":"Aphthous stomatitis","level":"III","imp":"Aphthous stomatitis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۲۵ ساله با زخم‌های دردناک متعدد مخاط لب و گونه از 3 روز.","why":"موضعی؛ بهبود 7 تا 10 روز."}],"ch":"152","name":"Aphthous stomatitis and oral cancer (leukoplakia / erythroplakia)","name_fa":"استوماتیت آفتی و سرطان دهان","cc":["ent"],"keywords":"aphthous ulcer, canker sore, triamcinolone dental paste, chlorhexidine, oral cancer, leukoplakia, erythroplakia, آفت دهان, سرطان دهان","status":"draft","features":["آفت: ضایعات دردناک، اغلب متعدد؛ مخاط لبی و باکال؛ 2 mm تا چند سانتی‌متر؛ بهبود 7 تا 10 روز","سرطان دهان: leukoplakia (پلاک سفید غیرقابل برداشتن) و erythroplakia؛ شایع‌ترین محل: لبه خلفی-جانبی زبان؛ علائم: درد، پارستزی، زخم پایدار، خونریزی، سفتی/induration، لنفادنوپاتی، اختلال عملکرد"],"ddx":[{"n":"Oral carcinoma / HSV gingivostomatitis / Behçet disease |","cm":1},{"n":"Candidiasis / hand-foot-mouth disease / HIV-related ulcers |"}],"redflags":["زخم پایدار > 14 روز، induration، لنفادنوپاتی، سیگار/الکل"],"guide":"آفت: triamcinolone acetonide 0.1% dental paste (Kenalog in Orabase) موضعی 2 تا 3 بار روزانه یا chlorhexidine 0.12% موضعی دو بار روزانه. سرطان: همه ضایعات مشکوک یا پایدار > 14 روز با وجود درمان: ارجاع اورژانس به جراح دهان برای بیوپسی.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 152: Oral and Dental Emergencies, pp. 838–844"},"dental-fracture-luxation-avulsion":{"id":"dental-fracture-luxation-avulsion","variants":[{"id":"dental-fracture-ellis","o":{"I":[{"t":"Facial / mandible imaging if clinical suspicion for alveolar ridge, maxillary or mandibular fracture"}],"S":[{"t":"Oral analgesics (NSAIDs)","fl":[{"k":"ci","v":"topical anesthetics contraindicated for home"}]}],"T":[{"t":"Ellis 1: smooth with emery board or refer for cosmetic repair"},{"t":"Ellis 2: dry the dentin and promptly cover with calcium hydroxide paste or glass ionomer cement; dentist within 24 h"},{"t":"Ellis 3 (pulp exposure): thin layer calcium hydroxide paste over pulp then glass ionomer cement over patch and dentin; dentist evaluation in ED ideally or within 24 h if small exposure","fl":[{"k":"note","v":"prophylactic antibiotics controversial"}]}],"Co":[{"t":"Dentist within 24 h"}]},"name":"Fractured tooth (Ellis 1–3)","level":"III","imp":"Dental fracture (Ellis class)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۲۰ ساله پس از ضربه به دهان با شکستگی ثنایای فوقانی؛ عاج زرد دیده می‌شود و به سرما حساس.","why":"پوشش عاج/پالپ و دندانپزشک ≤ 24 ساعت."},{"id":"dental-luxation","o":{"I":[{"t":"Dental / panoramic radiograph; imaging for alveolar / jaw fracture if suspected"}],"S":[{"t":"NSAIDs"}],"T":[{"t":"Extrusive luxation: gentle repositioning (dental block) and splint with zinc oxide periodontal dressing; lateral luxation with alveolar fracture: manual relocation possible, best with dentist; intrusive luxation: poor outcome"},{"t":"Soft diet; meticulous oral hygiene; chlorhexidine 0.12% mouth rinses twice daily"}],"Co":[{"t":"Dentist within 24 h (urgent referral for concussion / subluxation to exclude more severe injury)"}]},"name":"Dental concussion / subluxation / luxation (extrusive, lateral, intrusive)","level":"III","imp":"Dental luxation injury","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"کودک ۱۰ ساله پس از ضربه با ثنایای شل و نیمه‌خارج‌شده.","why":"جا انداختن و splint، دندانپزشک ≤ 24 ساعت."},{"id":"tooth-avulsion","o":{"I":[{"t":"If tooth missing or only partial tooth found: face, neck or chest radiographs (displaced / aspirated tooth)"}],"S":[{"t":"Local anesthesia; analgesia"},{"t":"Adults: doxycycline 100 mg PO twice daily for 7 days; children < 12 years: penicillin VK 12.5 mg/kg/dose four times daily for 7 days (after replantation)"}],"T":[{"t":"Permanent tooth avulsed < 3 h: replant immediately (handle by crown only; rinse < 10 s; replant at scene if possible; otherwise Hank's balanced salt solution / cold milk / saliva / saline; transport under tongue of alert cooperative patient or parent)"},{"t":"ED: gently rinse tooth (Hank's or saline); remove clot from socket with saline stream, examine socket (reposition wall fracture); open vs closed apex pathway; firmly replant, verify position clinically / radiographically; flexible splint up to 2 weeks (4 weeks if dry > 60 min)"},{"t":"Moist tooth with open apex: minocycline microspheres or 5-min doxycycline soak; dry time > 60 min: remove necrotic tissue, 2% stannous fluoride 20 min","fl":[{"k":"ci","v":"do NOT replant primary teeth in children"}]}],"Co":[{"t":"Early dentist consultation (do not delay replantation); tetanus update; consider abuse in child"}]},"name":"Tooth avulsion (permanent tooth knocked out)","level":"I","imp":"Dental avulsion","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"none","cxr":"PA","sc":"مرد ۱۸ ساله پس از ضربه با ثنیه دائمی کامل کنده‌شده 30 دقیقه پیش؛ دندان در شیر سرد.","why":"replant فوری؛ بدون انتظار دندانپزشک."}],"ch":"152","name":"Dental trauma — fractures (Ellis), concussion / luxation, and tooth avulsion","name_fa":"تروما دندان — شکستگی (Ellis)، لوکساسیون و آوالسیون","cc":["head-injury","ent","wound-bite"],"keywords":"dental avulsion, tooth replantation, Ellis fracture, luxation, subluxation, Hank solution, calcium hydroxide, tooth knocked out, آوالسیون دندان, شکستگی دندان","status":"draft","features":["Ellis: کلاس 1: فقط مینا: صاف با emery board یا ارجاع زیبایی؛ کلاس 2: عاج زرد کرمی زیر مینا سفید؛ حساسیت به هوا و دما: خشک کردن عاج و پوشاندن با calcium hydroxide یا glass ionomer؛ دندانپزشک ≤ 24 ساعت؛ کلاس 3: درگیری پالپ (لکه قرمز در عاج یا قطره خون پس از پاک کردن): لایه نازک calcium hydroxide روی پالپ + glass ionomer روی همه؛ دندانپزشک بر بالین ED ایده‌آل یا ≤ 24 ساعت؛ ضددرد خوراکی؛ بی‌حس‌کننده موضعی ممنوع؛ آنتی‌بیوتیک پروفیلاکتیک بحث‌برانگیز","concussion: حساسیت به پرکاشن بدون تحرک؛ subluxation: تحرک پس از تروما بدون جابه‌جایی؛ NSAID و رژیم نرم و ارجاع فوری؛ extrusive luxation: خروج نسبی از آلوئول: جا انداختن ملایم (بلوک دندانی) و splint با zinc oxide؛ دندانپزشک ≤ 24 ساعت؛ lateral luxation با شکستگی آلوئول: جا انداختن دستی ممکن ولی بهتر با مشاوره دندانپزشک؛ intrusive: پیش‌آگهی بد؛ همه luxation: رژیم نرم، بهداشت دهان، chlorhexidine 0.12% دو بار روزانه و ارجاع ≤ 24 ساعت","avulsion: اورژانس واقعی؛ دندان شیری جایگزین نمی‌شود؛ دائمی < 3 ساعت: فوراً replant؛ صحنه: فقط تاج، شستشو با آب < 10 ثانیه و replant؛ در غیر امکان (خطر آسپیراسیون): نگهداری در Hank's solution (4 تا 6 ساعت)، شیر سرد، بزاق یا سالین؛ زیر زبان بیمار هوشیار/والد؛ اتاق عمل: شستشو، لخته حفره را بردار، آپکس باز یا بسته"],"ddx":[{"n":"Alveolar ridge / mandible / maxilla fracture |","cm":1},{"n":"Aspirated tooth (CXR) / child abuse |"}],"redflags":["آوالسیون، دندان گم‌شده (آسپیراسیون)، شک سوءاستفاده کودک، شکستگی فک"],"guide":"جدول 152-1 replantation: دندان مرطوب با آپکس باز در محیط مناسب و/یا < 60 دقیقه خشک: شستشوی ریشه با سالین، پوشش minocycline microspheres یا خیساندن 5 دقیقه در doxycycline (1 mg/20 mL سالین)، بی‌حسی موضعی، برداشتن لخته حفره با جریان سالین و بررسی شکستگی دیواره، replant محکم و تأیید موقعیت بالینی/رادیوگرافی، splint انعطاف‌پذیر تا 2 هفته؛ آپکس بسته: همین بدون minocycline؛ خشک > 60 دقیقه یا سلول غیرزنده: برداشتن بافت نرم نکروتیک با گاز، غوطه‌وری در stannous fluoride 2% به مدت 20 دقیقه، سپس replant و splint تا 4 هفته. مشاوره دندانپزشک زودهنگام ولی replant را تأخیر نده. پس از replant: بزرگسال doxycycline 100 mg PO دو بار × 7 روز؛ کودک < 12 سال penicillin VK 12.5 mg/kg/dose چهار بار × 7 روز؛ دندان گم‌شده: جستجوی بافت مجاور؛ اگر نیافت یا قطعه جزئی: رادیوگرافی صورت/گردن/قفسه برای دندان جابه‌جا یا آسپیره. آسیب‌های همراه: تصویربرداری برای شکستگی آلوئول/ماگزیلا/مندیبل. پیش‌آگهی ممکن ضعیف (50% نکروز پالپ در 1.5 سال در extrusive).","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 152: Oral and Dental Emergencies, pp. 838–844"},"oral-soft-tissue-laceration":{"id":"oral-soft-tissue-laceration","variants":[{"id":"tongue-laceration-main","o":{"I":[{"t":"(dental / facial imaging if teeth / fracture suspected)"}],"S":[{"t":"Topical 4% lidocaine on gauze for 5 min; local infiltration 1% lidocaine with epinephrine or bilateral lingual nerve block if needed"}],"T":[{"t":"Stabilize dental trauma first; search for retained foreign body; tetanus update; consider abuse in children"},{"t":"Primary closure indications: bisection, widely gaping at rest, active bleeding, flap / U-shaped, tongue edge, > 1 cm; non-gaping superficial linear < 1 cm central dorsal needs no repair"},{"t":"Repair with 4-0 or 5-0 absorbable sutures, loose, wide and deep; ≥ 4 knots; dental bite block"}],"Co":[{"t":"Emergent specialty consultation for sedation needs, large / complex lacerations, partial / full amputation, hemostasis difficulty; aftercare as intraoral lacerations"}]},"name":"Tongue / intraoral laceration","level":"III","imp":"Tongue / intraoral laceration","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"کودک ۷ ساله با لاسراسیون 1.5 cm لبه زبان پس از افتادن.","why":"بستن اولیه لبه زبان با بخیه absorbable؛ ردّ تروما همراه."}],"ch":"152","name":"Oral soft tissue trauma — lip, frenulum and tongue lacerations","name_fa":"تروما بافت نرم دهان — لاسراسیون لب، فرنولوم و زبان","cc":["wound-bite","ent"],"keywords":"tongue laceration, frenulum laceration, lip laceration, intraoral laceration, lingual nerve block, absorbable suture, لاسراسیون زبان, فرنولوم","status":"draft","features":["ابتدا ترومای دندانی را تثبیت کن سپس بافت نرم؛ جستجوی کامل جسم خارجی؛ کزاز؛ در کودک شک سوءاستفاده","فرنولوم ماگزیلاری لابیال معمولاً ترمیم نمی‌خواهد؛ فرنولوم لینگوال بسیار عروقی: معمولاً با بخیه absorbable 4-0 ترمیم","زبان: عروقی؛ خونریزی عظیم یا تورم تأخیری وریدی ممکن راه هوایی را مسدود کند؛ اندیکاسیون ترمیم بحث‌برانگیز؛ اندیکاسیون‌های بستن اولیه: دو نیم شدن زبان، زخم باز در استراحت، خونریزی فعال، فلپ یا U شکل، لبه زبان، > 1 cm؛ بدون ترمیم: سطحی غیرباز خطی < 1 cm مرکز پشت زبان"],"ddx":[{"n":"Airway compromise (tongue swelling / bleeding) |","cm":1},{"n":"Retained tooth fragment / foreign body |"}],"redflags":["خونریزی غیرقابل کنترل، قطع نسبی/کامل زبان، پیچیده"],"guide":"بی‌حسی: گاز آغشته به lidocaine 4% موضعی 5 دقیقه؛ گاه تزریق lidocaine 1% با epinephrine یا بلوک عصب لینگوال دوطرفه (2/3 قدامی). کنترل بیشتر: گرفتن نوک زبان با towel clamp یا بخیه سیلک موقت؛ bite block. ترمیم با بخیه absorbable 4-0 یا 5-0؛ شل، پهن و عمیق (برای ادم 2 روز اول)؛ تمام لایه‌ها با یک بخیه منفرد یا دو/سه لایه؛ در کودک ممکن فقط لایه عضله عمقی؛ لبه‌ها دقیق؛ هر بخیه ≥ 4 گره؛ حدود 7 روز بخیه‌ها می‌افتند. مشاوره تخصصی اورژانس: لاسراسیون نیازمند sedation رویه‌ای، بزرگ/پیچیده، قطع کامل/نسبی و مشکل در هموستاز.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 152: Oral and Dental Emergencies, pp. 838–844"},"pharyngitis-tonsillitis-adult":{"id":"pharyngitis-tonsillitis-adult","variants":[{"id":"pharyngitis-viral","o":{"L":[{"t":"Rapid antigen test if ≥ 2 Centor criteria; monospot / influenza / HIV testing if suspected"}],"S":[{"t":"IV fluids if dehydrated ; analgesics / antipyretics","fl":[{"k":"ci","v":"caution in heart failure / CKD"}]}],"T":[{"t":"Supportive care (throat lozenges, saline gargles, hydration)"}],"Co":[{"t":"Discharge with return precautions"}]},"name":"Viral pharyngitis / tonsillitis","level":"III","imp":"Viral pharyngitis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۲۵ ساله با گلودرد، سرفه، آبریزش بینی و تب خفیف؛ بدون exudate.","why":"حمایتی؛ تست استرپ اگر ≥ 2 معیار Centor."},{"id":"pharyngitis-gabhs","o":{"L":[{"t":"Rapid antigen test (± throat culture); additional testing if mononucleosis / influenza / acute retroviral syndrome suspected"}],"S":[{"t":"Antipyretics / analgesics"}],"A":[{"t":"Benzathine penicillin G 1.2 million units IM single dose, OR penicillin VK 500 mg PO twice daily for 10 days, OR amoxicillin 500 mg PO twice daily (or 1000 mg/day)","fl":[{"k":"ci","v":"penicillin allergy → first-generation cephalosporin or clindamycin"}]}],"Co":[{"t":"Discharge with return precautions; PCP follow-up"}]},"name":"GABHS pharyngitis (Centor ≥ 2 and positive rapid antigen test)","level":"III","imp":"Group A streptococcal pharyngitis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۲۰ ساله با تب، گلودرد شدید، exudate لوزه، آدنوپاتی قدامی دردناک و بدون سرفه؛ تست سریع مثبت.","why":"پنی‌سیلین؛ تست بر اساس Centor."}],"ch":"153","name":"Pharyngitis and tonsillitis (viral and GABHS) — adult","name_fa":"فارنژیت و تونسیلیت (ویروسی و استرپتوکوک گروه A)","cc":["ent","fever"],"keywords":"pharyngitis, tonsillitis, strep throat, GABHS, Centor criteria, rapid antigen test, benzathine penicillin, سرماخوردگی گلو, گلودرد استرپتوکوکی","status":"draft","features":["ویروسی: تب، اودینوفاژی و ضایعات پتشیال یا وزیکولار کام نرم و لوزه؛ بیشتر همراه سرفه، آبریزش بینی و احتقان؛ معمولاً بدون exudate لوزه و آدنوپاتی گردنی","باکتریال (GABHS): شروع حاد تب، گلودرد، اودینوفاژی و اغلب سردرد؛ اریتم لوزه، exudate و آدنوپاتی دردناک قدامی گردن؛ بدون سرفه، ورم ملتحمه و آبریزش بینی","معیار Centor: (1) exudate لوزه، (2) آدنوپاتی دردناک قدامی گردن، (3) نبود سرفه، (4) تب؛ ≥ 2 معیار: تست آنتی‌ژن سریع و درمان بر اساس نتیجه؛ تست بیشتر اگر مونونوکلئوز، آنفلوانزا یا سندرم رتروویروس حاد مشکوک"],"ddx":[{"n":"Peritonsillar / retropharyngeal abscess / epiglottitis |","cm":1},{"n":"Infectious mononucleosis / acute HIV / influenza / diphtheria |"}],"redflags":["trismus، صدای خفه، ریزش بزاق، استریدور، ناتوانی در بلع مایعات"],"guide":"غیرباکتریال: حمایتی: ضدتب، ضددرد و مایع IV در کم‌آبی. GABHS: یک دوز benzathine penicillin G 1.2 میلیون واحد IM یا penicillin VK 500 mg PO دو بار روزانه × 10 روز یا amoxicillin 500 mg دو بار (یا 1000 mg روزانه)؛ آلرژی پنی‌سیلین: سفالوسپورین نسل اول یا clindamycin.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 153: Neck and Upper Airway Disorders, pp. 845–850"},"peritonsillar-abscess-adult":{"id":"peritonsillar-abscess-adult","variants":[{"id":"pta-main","o":{"I":[{"t":"Intraoral ultrasound (very sensitive / specific if diagnosis in question); CT neck with contrast if concern for extension beyond peritonsillar space"}],"L":[{"t":"CBC; culture of pus; rapid strep / monospot as indicated"}],"S":[{"t":"IV fluids if dehydrated; analgesics; local anesthesia (e.g., lidocaine) for procedure"}],"A":[{"t":"Penicillin VK PLUS metronidazole 500 mg PO every 8 h for 10 days after adequate drainage (penicillin-allergic: clindamycin)"}],"T":[{"t":"Needle aspiration with 18-gauge needle (cut plastic sheath ~1 cm from tip to avoid internal carotid artery) or incision and drainage after local anesthesia"}],"Co":[{"t":"ENT if no drainage / large abscess / recurrent; discharge if tolerates PO with follow-up"}]},"name":"Peritonsillar abscess (drainage; oral antibiotics if tolerates PO)","level":"II","imp":"Peritonsillar abscess","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۲۵ ساله با گلودرد یک‌طرفه شدید، trismus، صدای خفه و انحراف uvula به راست.","why":"آسپیراسیون/I&D و آنتی‌بیوتیک."},{"id":"pta-toxic","o":{"I":[{"t":"CT neck with contrast"}],"L":[{"t":"CBC, electrolytes, creatinine, blood cultures, lactate"}],"S":[{"t":"IV fluids","fl":[{"k":"ci","v":"caution in heart failure"}]}],"A":[{"t":"Piperacillin-tazobactam 3.375 g IV","fl":[{"k":"hi","v":""}]}],"T":[{"t":"Needle aspiration / I&D; airway monitoring"}],"Co":[{"t":"ENT consultation; admit for observation"}]},"name":"Toxic peritonsillar abscess / unable to tolerate PO","level":"I","imp":"Peritonsillar abscess, toxic","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مرد ۴۵ ساله با آبسه پری‌تانسیلار، تب 39.5، تاکی‌کاردی و ناتوان در بلع.","why":"آنتی‌بیوتیک IV و بستری."}],"ch":"153","name":"Peritonsillar abscess (adult)","name_fa":"آبسه پری‌تانسیلار (بزرگسال)","cc":["ent","fever"],"keywords":"peritonsillar abscess, quinsy, needle aspiration, trismus, uvula deviation, penicillin metronidazole, آبسه اطراف لوزه, کوینزی","status":"draft","features":["بیمار بدحال با گلودرد، تب، اودینوفاژی، trismus و دیسفاژی؛ صدای خفه (hot potato)؛ لوزه مبتلا به داخل جابه‌جا شده و انحراف uvula به سمت مقابل","افتراق: سلولیت پری‌تانسیلار، مونونوکلئوز، آبسه رتروفارنژیال، تونسیلیت HSV، نئوپلاسم و آنوریسم کاروتید داخلی؛ تشخیص بالینی؛ سونوگرافی داخل‌دهانی بسیار حساس و اختصاصی؛ CT با کنتراست اگر نگرانی گسترش"],"ddx":[{"n":"Retropharyngeal abscess / deep neck infection / Ludwig angina |","cm":1},{"n":"Peritonsillar cellulitis / mononucleosis / internal carotid aneurysm |"}],"redflags":["trismus، استریدور، سمیت سیستمیک، گسترش گردنی"],"guide":"آسپیراسیون با سوزن 18G یا I&D پس از بی‌حسی موضعی؛ غلاف پلاستیکی سوزن را حدود 1 cm از نوک ببر تا از نفوذ تا سطح کاروتید داخلی جلوگیری شود. پس از تخلیه کافی: بیمار با تحمل PO ترخیص با antibiotic: penicillin VK + metronidazole × 10 روز؛ آلرژی پنی‌سیلین: clindamycin. بیمار سمی: piperacillin-tazobactam 3.375 g IV و بستری مشاهده.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 153: Neck and Upper Airway Disorders, pp. 845–850"},"epiglottitis-adult":{"id":"epiglottitis-adult","variants":[{"id":"epiglottitis-main","o":{"I":[{"t":"Lateral cervical soft tissue radiograph (vallecula obliteration, \"thumb print sign\") only if stable — do not delay airway; transnasal fiberoptic laryngoscopy (ENT)"}],"L":[{"t":"CBC, blood cultures (after airway secured), electrolytes"}],"S":[{"t":"IV hydration"},{"t":"Methylprednisolone 125 mg IV (may reduce airway inflammation and edema)"}],"A":[{"t":"Cefotaxime 50 mg/kg IV plus vancomycin 15 mg/kg IV ; penicillin-allergic: respiratory fluoroquinolone","fl":[{"k":"hi","v":""}]}],"T":[{"t":"Keep patient upright; humidified oxygen; cardiac monitor; pulse oximetry; surgical airway equipment ready (emergency physician must be prepared)"},{"t":"Endotracheal intubation generally in OR via awake fiberoptic method (or ED with sufficient expertise and equipment)"}],"Co":[{"t":"Immediate otolaryngology consultation; ICU admission"}]},"name":"Adult epiglottitis","level":"I","imp":"Adult epiglottitis (supraglottitis)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"humidified oxygen","sc":"مرد ۴۰ ساله با گلودرد شدید، ریزش بزاق، صدای خفه و استریدور؛ نشسته و رو به جلو.","why":"مشاوره فوری ENT و راه هوایی ایمن؛ نه دستکاری."}],"ch":"153","name":"Adult epiglottitis (supraglottitis)","name_fa":"اپی‌گلوتیت بزرگسال (supraglottitis)","cc":["ent","dyspnea"],"keywords":"epiglottitis, supraglottitis, thumb sign, tripod position, drooling, stridor, awake fiberoptic intubation, اپی گلوتیت","status":"draft","features":["1 تا 2 روز دیسفاژی، اودینوفاژی و تنگی نفس بدتر شونده (بدتر در خوابیده)؛ حساسیت قدام گردن با لمس ملایم حنجره و نای فوقانی؛ وضعیت کلاسیک: نشسته رو به جلو، دهان باز و گردن اکستنسور؛ آب‌ریزش بزاق و استریدور دمی","تشخیص: شرح حال و معاینه، رادیوگرافی نسج نرم جانبی گردن: محو شدن vallecula و «thumb print sign» و/یا لارنگوسکوپی فیبراپتیک ترانس‌ناسال"],"ddx":[{"n":"Retropharyngeal abscess / angioedema / foreign body |","cm":1},{"n":"Peritonsillar abscess / croup (peds) / laryngeal tumor |"}],"redflags":["استریدور، ریزش بزاق، وضعیت tripod، ناتوانی در بلع"],"guide":"مشکوک: مشاوره فوری ENT؛ آماده راه هوایی جراحی. بیمار در وضعیت نشسته بماند؛ اکسیژن مرطوب، مایع IV، مانیتور قلبی و پالس‌اکسیمتری. آنتی‌بیوتیک خط اول: cefotaxime 50 mg/kg + vancomycin 15 mg/kg IV؛ آلرژی پنی‌سیلین: فلوروکینولون تنفسی؛ methylprednisolone 125 mg IV ممکن التهاب و ادم را کم کند. اینتوباسیون معمولاً در اتاق عمل به روش «awake» فیبراپتیک؛ با تخصص و تجهیزات کافی در ED ممکن.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 153: Neck and Upper Airway Disorders, pp. 845–850"},"retropharyngeal-abscess-adult":{"id":"retropharyngeal-abscess-adult","variants":[{"id":"rpa-adult-main","o":{"I":[{"t":"CT neck with IV contrast (gold standard); lateral neck radiograph if CT delayed; CXR (mediastinal extension)"}],"L":[{"t":"CBC, CRP, electrolytes, creatinine, blood cultures"}],"S":[{"t":"IV fluids","fl":[{"k":"ci","v":"caution in heart failure"}]}],"A":[{"t":"Clindamycin IV (600 mg every 8 h) or cefoxitin IV","fl":[{"k":"hi","v":""}]}],"T":[{"t":"Prepare for emergent airway management as needed; upright position"}],"Co":[{"t":"Early otolaryngology consultation (drainage); ICU / admit"}]},"name":"Retropharyngeal abscess","level":"I","imp":"Retropharyngeal abscess","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مرد ۴۰ ساله با گلودرد، تورم گردن، دیسفاژی و تب؛ CT: کلکسیون رتروفارنژیال.","why":"CT، آنتی‌بیوتیک IV و ENT زودهنگام."}],"ch":"153","name":"Retropharyngeal abscess (adult)","name_fa":"آبسه رتروفارنژیال (بزرگسال)","cc":["ent","fever"],"keywords":"retropharyngeal abscess, neck CT, torticollis, clindamycin, cefoxitin, آبسه رتروفارنکس","status":"draft","features":["گلودرد، درد گردن، torticollis و دیسفاژی؛ صدای خفه، آدنوپاتی گردنی و دیسترس تنفسی؛ استریدور در کودک شایع‌تر","CT گردن با کنتراست IV استاندارد طلایی و سلولیت را از آبسه تمیز می‌کند"],"ddx":[{"n":"Epiglottitis / peritonsillar abscess / Ludwig angina |","cm":1},{"n":"Vertebral osteomyelitis / meningitis / torticollis |"}],"redflags":["استریدور، دیسترس تنفسی، trismus، سپسیس"],"guide":"آماده برای مدیریت اورژانس راه هوایی؛ مشاوره زودهنگام ENT؛ مایع IV و clindamycin یا cefoxitin IV.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 153: Neck and Upper Airway Disorders, pp. 845–850"},"odontogenic-neck-abscess-ludwig":{"id":"odontogenic-neck-abscess-ludwig","variants":[{"id":"odontogenic-abscess-drainage","o":{"I":[{"t":"Bedside ultrasound (superficial abscess); CT neck with contrast if deep space suspected"}],"S":[{"t":"Analgesics; local anesthesia for drainage"}],"A":[{"t":"Penicillin VK or amoxicillin PO after drainage; penicillin-allergic: clindamycin or levofloxacin"}],"T":[{"t":"Surgical drainage (I&D in ED or operating room)"}],"Co":[{"t":"Dentist / OMFS follow-up"}]},"name":"Odontogenic abscess (gingival / buccal) — drainage and oral antibiotics","level":"III","imp":"Odontogenic abscess","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۳۰ ساله با آبسه لثه پایین، تورم گونه و تب خفیف؛ بدون trismus.","why":"I&D و آنتی‌بیوتیک خوراکی."},{"id":"deep-neck-ludwig-necrotizing","o":{"I":[{"t":"CT neck with IV contrast; CXR PA (mediastinitis)"}],"L":[{"t":"CBC, CRP, glucose, electrolytes, creatinine, lactate, blood cultures"}],"S":[{"t":"IV fluid resuscitation, vasopressors if shock","fl":[{"k":"ci","v":"caution in heart failure"}]}],"A":[{"t":"Ampicillin/sulbactam IV plus clindamycin plus ciprofloxacin","fl":[{"k":"hi","v":""}]}],"T":[{"t":"Early airway control (awake fiberoptic / surgical airway readiness); wide local debridement / fasciotomy for necrotizing infection"}],"Co":[{"t":"Immediate surgical consultation (ENT / OMFS); ICU"}]},"name":"Deep space neck infection / Ludwig's angina / necrotizing infection","level":"I","imp":"Deep space neck infection / Ludwig's angina","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"PA","sc":"مرد ۵۰ ساله دیابتی با تورم گردن و کف دهان، trismus، crepitus و فشار 85/50.","why":"راه هوایی، آنتی‌بیوتیک وسیع‌الطیف و جراحی فوری."}],"ch":"153","name":"Odontogenic abscess, deep space neck infection and Ludwig's angina (necrotizing)","name_fa":"آبسه دندانی، عفونت فضای عمیق گردن و Ludwig (نکروزان)","cc":["ent","fever"],"keywords":"odontogenic abscess, deep space neck infection, Ludwig angina, necrotizing fasciitis neck, ampicillin-sulbactam, clindamycin, ciprofloxacin, آبسه دندانی, Ludwig","status":"draft","features":["بیشتر عفونت‌های فضای عمیق گردن دندانی (معمولاً دندان‌های مندیبل)؛ trismus، تب، توده گردن، دیسفاژی و تنگی نفس؛ از سلولیت منتشر تا آبسه لثه لبی/باکال؛ گسترش از لایه‌های فاشیال به فضاهای بالقوه صورت، گردن و دهان","سونوگرافی بالین: آبسه سطحی؛ شک فضای عمیق: CT گردن با کنتراست","Ludwig: عفونت فضاهای submental، sublingual و submandibular: trismus و ادم کل گردن فوقانی و کف دهان؛ بیمار بحرانی: عفونت نکروزان: تغییر رنگ پوست، crepitus زیرجلدی، تب، تاکی‌کاردی، هیپوتانسیون و گیجی"],"ddx":[{"n":"Necrotizing fasciitis / mediastinitis / airway obstruction |","cm":1},{"n":"Retropharyngeal abscess / parotitis / angioedema |"}],"redflags":["trismus، ادم کف دهان، crepitus، سپسیس، تنگی نفس"],"guide":"درناژ جراحی (I&D در ED یا اتاق عمل). ترخیص پس از درناژ: penicillin VK یا amoxicillin؛ آلرژی پنی‌سیلین: clindamycin یا levofloxacin. فضای عمیق گردن: ampicillin/sulbactam IV + clindamycin + ciprofloxacin. Ludwig: مشاوره فوری جراحی؛ بیماران نیاز به fasciotomy با debridement وسیع و آنتی‌بیوتیک وسیع‌الطیف IV دارند.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 153: Neck and Upper Airway Disorders, pp. 845–850"},"neck-mass-adult":{"id":"neck-mass-adult","variants":[{"id":"neck-mass-main","o":{"I":[{"t":"Flexible nasopharyngolaryngoscopy if airway compromise / dysphagia / odynophagia (before CT); CT neck with contrast (extent of mass); CXR PA"}],"L":[{"t":"CBC, ESR, TSH; HIV / TB screening as indicated"}],"A":[{"t":"Inflammatory lymph node: cephalexin 500 mg PO three to four times daily, or amoxicillin 500 mg three to four times daily, or clindamycin 300 mg three to four times daily"},{"t":"Sialoadenitis: clindamycin (staphylococcal coverage)"}],"Co":[{"t":"Urgent ENT referral for persistent mass > 6 weeks (biopsy); oncology"}]},"name":"Neck mass (inflammatory vs neoplastic)","level":"III","imp":"Neck mass","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"PA","sc":"مرد ۵۵ ساله سیگاری با توده جانبی گردن 2 ماهه، بی‌درد.","why":"ارجاع ENT برای بیوپسی؛ آنتی‌بیوتیک فقط اگر التهابی."}],"ch":"153","name":"Neck and upper airway masses (adult)","name_fa":"توده‌های گردن و راه هوایی فوقانی (بزرگسال)","cc":["ent"],"keywords":"neck mass, lymphadenopathy, malignancy, lateral neck mass, flexible nasopharyngolaryngoscopy, توده گردن","status":"draft","features":["مادرزادی، عفونی، غددی یا نئوپلاستیک؛ بالغ > 40 سال: تا 80% توده‌های جانبی گردن پایدار > 6 هفته بدخیم","جدول 153-1: جوان: لنفادنوپاتی واکنشی، مونونوکلئوز، لنفوم، branchial cleft cyst، thyroglossal duct cyst، TB؛ بالغ مسن: کارسینوم متاستاتیک مجرای هوایی-گوارشی، عفونت/نئوپلاسم غدد بزاقی، لنفوم، اختلال تیروئید","بیمار با اختلال راه هوایی یا دیسفاژی/اودینوفاژی قابل‌توجه: flexible nasopharyngolaryngoscopy قبل از CT؛ CT برای برنامه جراحی"],"ddx":[{"n":"Airway compromise from mass |","cm":1},{"n":"Reactive lymph node / abscess / thyroid disease |"}],"redflags":["تنگی نفس، استریدور، دیسفاژی، توده سفت > 6 هفته، سیگار/الکل"],"guide":"غدد التهابی: آنتی‌بیوتیک تجربی: cephalexin 500 mg PO سه تا چهار بار روزانه یا amoxicillin 500 mg سه تا چهار بار یا clindamycin 300 mg سه تا چهار بار. sialoadenitis: پوشش استافیلوکوک مثل clindamycin.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 153: Neck and Upper Airway Disorders, pp. 845–850"},"post-tonsillectomy-bleeding":{"id":"post-tonsillectomy-bleeding","variants":[{"id":"post-tonsillectomy-main","o":{"L":[{"t":"CBC, PT/INR, aPTT, type and crossmatch"}],"S":[{"t":"IV access; crystalloid / blood products as needed for hemorrhagic shock","fl":[{"k":"ci","v":"caution in heart failure"}]}],"T":[{"t":"Keep patient NPO and sitting upright; direct pressure with tonsillar pack or 4×4 gauze on long clamp moistened with thrombin or lidocaine + epinephrine; or local infiltration of lidocaine with epinephrine then silver nitrate cautery if site visualized"},{"t":"Massive bleeding: intubation is the only means to protect airway — plan emergent cricothyrotomy before attempting intubation"}],"Co":[{"t":"Early otolaryngology consultation (OR if persistent bleeding); admit"}]},"name":"Post-tonsillectomy hemorrhage","level":"I","imp":"Post-tonsillectomy bleeding","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"none","sc":"کودک/بزرگسال روز 7 پس از تونسیلکتومی با خونریزی روشن از دهان و تاکی‌کاردی.","why":"فشار موضعی و ENT زودهنگام؛ راه هوایی."}],"ch":"153","name":"Post-tonsillectomy bleeding","name_fa":"خونریزی پس از تونسیلکتومی","cc":["bleeding-bruising","ent"],"keywords":"post-tonsillectomy hemorrhage, tonsillar bleeding, tonsillar pack, silver nitrate, cricothyrotomy, خونریزی پس از تونسیلکتومی","status":"draft","features":["عارضه شناخته‌شده؛ مرگ از انسداد راه هوایی یا شوک هموراژیک؛ بروز 1 تا 8.8% و حدود نیمی نیاز به جراحی؛ بیشتر روز 5 تا 10 ولی ممکن ظرف 24 ساعت"],"ddx":[{"n":"Airway obstruction / hemorrhagic shock |","cm":1}],"redflags":["خونریزی فعال، استفراغ خون، تاکی‌کاردی، شوک"],"guide":"NPO و نشسته. مشاوره زودهنگام ENT. فشار مستقیم روی بستر لوزه با tonsillar pack یا گاز 4×4 روی کلامپ بلند مرطوب‌شده با thrombin یا lidocaine+epinephrine. یا اگر محل دیده می‌شود: تزریق موضعی lidocaine با epinephrine و cautery با silver nitrate. خونریزی ماسیو نادر: اینتوباسیون تنها راه محافظت راه هوایی؛ پیش از تلاش برای اینتوباسیون cricothyrotomy اورژانس برنامه‌ریزی شود.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 153: Neck and Upper Airway Disorders, pp. 845–850"},"tracheostomy-complications":{"id":"tracheostomy-complications","variants":[{"id":"trach-obstruction-dislodgement","o":{"I":[{"t":"CXR portable (tube position; extrinsic tracheal compression suggesting dislodgement)"}],"L":[{"t":"Blood gas"}],"T":[{"t":"If tube patent: leave in place; suction (preoxygenate, instill sterile saline into trachea); remove inner cannula, occasionally entire tube if suctioning fails"},{"t":"If dislodged: remove entire tube; insert nasopharyngoscope / flexible bronchoscope into stoma to identify true tracheal opening; if cannot: ENT / surgery; if cannot maintain airway: orally intubate (cuffed tube for ventilation)"},{"t":"Passy-Muir valve: remove first if respiratory distress / inability to speak, then check tube for obstruction"}],"Co":[{"t":"ENT / general surgery; ICU"}]},"name":"Tracheostomy tube obstruction / dislodgement","level":"I","imp":"Tracheostomy tube obstruction / dislodgement","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"high-flow oxygen to stoma and mouth","sc":"بیمار تراکئوستومی‌شده با تنگی نفس ناگهانی، SpO2 80% و کاتتر ساکشن عبور نمی‌کند.","why":"inner cannula را خارج؛ در عدم رفع: لوله را خارج و اینتوباسیون."},{"id":"trach-infection-bleeding","o":{"I":[{"t":"CXR portable; CT neck / chest with contrast if hemodynamically stable (fistula / stenosis)"}],"L":[{"t":"CBC, coagulation, type and crossmatch (bleeding); culture of stoma discharge, sputum culture (infection)"}],"A":[{"t":"Stable polymicrobial stoma infection / tracheitis: amoxicillin-clavulanate 875 mg PO twice daily; unstable / systemic: piperacillin-tazobactam 3.375 g IV plus vancomycin 1 g IV; add fluoroquinolone for Pseudomonas; local wound infection: gauze soaked in 0.25% acetic acid"}],"T":[{"t":"Slow bleeding: packing with saline-soaked gauze; if ineffective remove tube, examine stoma / trachea; local silver nitrate; brisk bleeding: replace with cuffed endotracheal tube with cuff below bleeding site"},{"t":"Tracheoinnominate fistula: hyperinflate cuff; if persistent slowly withdraw tube with anterior pressure on trachea; if fails: orally place ET tube above fistula under fiberoptic visualization while assistant removes trach tube; digital pressure of innominate artery against manubrium"},{"t":"Tracheal stenosis: humidified oxygen, nebulized racemic epinephrine, steroids"}],"Co":[{"t":"Immediate otolaryngology / thoracic surgery consultation; ICU"}]},"name":"Tracheostomy site infection / bleeding / stenosis / tracheoinnominate fistula","level":"I","imp":"Tracheostomy site infection / bleeding / tracheoinnominate fistula / stenosis","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","sc":"بیمار 10 روز پس از تراکئوستومی با خونریزی روشن از استوما و هموپتیزی؛ یا با قرمزی و ترشح چرکی استوما.","why":"بخش بحرانی: TIF را تشخیص و کاف hyperinflate؛ عفونت: آنتی‌بیوتیک."}],"ch":"153","name":"Tracheostomy complications (obstruction, dislodgement, infection, bleeding, tracheoinnominate fistula, stenosis)","name_fa":"عوارض تراکئوستومی","cc":["airway-procedure","dyspnea","bleeding-bruising"],"keywords":"tracheostomy, tracheostomy obstruction, decannulation, tracheoinnominate fistula, tracheal stenosis, stoma infection, عوارض تراکئوستومی","status":"draft","features":["زودرس (هفته اول): خونریزی، انسداد، جابه‌جایی و عفونت؛ دیررس: گرانولاسیون، تنگی نای و فیستول؛ EP باید تبدیل لوله بدون کاف به با کاف، جایگذاری مجدد پس از decannulation تصادفی، رفع انسداد و کنترل خونریزی/عفونت را بلد باشد","انسداد: اگر لوله باز است در جای بماند؛ مسدود شدن مخاط در نای یا برونش اصلی دیستال: ساکشن؛ preoxygenation و سالین استریل؛ خارج کردن inner cannula و گاه کل لوله","جابه‌جایی: کاتتر ساکشن عبور نمی‌کند و در گرافی لوله فشار خارجی بر نای دارد: کل لوله را خارج کن؛ nasopharyngoscope یا برونکوسکوپ در استوما برای یافتن مجرای نای؛ اگر ناموفق: ENT یا جراحی؛ اگر راه هوایی حفظ نمی‌شود: اینتوباسیون دهانی","عفونت: پوست استوما، تراکئیت و برونشیت راجعه؛ پایدار: amoxicillin-clavulanate 875 mg PO دو بار روزانه؛ ناپایدار/سیستمیک: piperacillin-tazobactam 3.375 g IV + vancomycin 1 g IV؛ افزودن فلوروکینولون برای Pseudomonas؛ عفونت موضعی زخم: گاز آغشته به acetic acid 0.25%","خونریزی: گرانولاسیون استوما، نای یا تیروئید یا فرسایش عروق تیروئید، دیواره نای یا شریان innominate؛ خفیف: پک با گاز آغشته به سالین؛ ناموفق: خارج کردن لوله و معاینه؛ موضعی: silver nitrate؛ شدید: جایگزین با لوله اندوتراکئال کافدار با کاف پایین‌تر از محل خونریزی","فیستول tracheoinnominate: نادر و تهدیدکننده؛ معمولاً 3 هفته اول؛ فرسایش از فشار کاف بالا (> 25 mmHg) یا نوک لوله؛ ممکن هموپتیزی یا sentinel bleed؛ مشاوره فوری ENT یا جراحی توراکس؛ خونریزی ماسیو: اولین مانور hyperinflation کاف؛ ادامه: خارج کردن آهسته لوله با فشار قدامی روی نای؛ ناموفق: لوله اندوتراکئال از بالای فیستول با دید مستقیم فیبراپتیک هنگام خارج کردن لوله تراکئوستومی؛ سپس فشار انگشت شریان innominate روی manubrium","تنگی نای: هفته‌ها تا ماه‌ها پس از decannulation؛ تنگی نفس، ویزینگ، استریدور و ناتوانی در پاک کردن ترشحات: اکسیژن مرطوب، racemic epinephrine نبولایز و استروئید؛ برونکوسکوپی rigid، لیزر، stent یا بازسازی","تعویض لوله: < 7 روز و غیراورژانس: توسط جراح آشنا (مسیر نابالغ؛ ایجاد مسیر کاذب)؛ مسیر در چاقی یا توده گردن به‌راحتی فرو می‌ریزد"],"ddx":[{"n":"Tracheoinnominate fistula / tube obstruction / pneumothorax |","cm":1},{"n":"Pneumonia / mucus plug / bronchospasm |"}],"redflags":["دیسترس تنفسی، خونریزی روشن، sentinel bleed، لوله غیرقابل عبور"],"guide":"مطابق ویژگی‌های بالا.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 153: Neck and Upper Airway Disorders, pp. 845–850"},"laryngectomy-airway":{"id":"laryngectomy-airway","variants":[{"id":"laryngectomy-main","o":{"I":[{"t":"CXR portable"}],"T":[{"t":"Remove speech valve (Passy-Muir) first; check tracheostomy tube for obstruction; suction"},{"t":"Supplemental oxygen via stoma; emergency intubation by placing endobronchial tube into tracheostoma (do not advance too far — carina 4–6 cm from stoma); oral intubation impossible"}],"Co":[{"t":"ENT; ICU if required"}]},"name":"Laryngectomy patient in respiratory distress","level":"I","imp":"Respiratory distress in laryngectomy patient","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"high-flow oxygen via stoma","sc":"بیمار لارنژکتومی‌شده با تنگی نفس و Passy-Muir valve؛ SpO2 82%.","why":"دریچه را بردار؛ انسداد را رفع."}],"ch":"153","name":"Laryngectomy patient — airway emergencies and speech devices","name_fa":"بیمار لارنژکتومی — اورژانس راه هوایی","cc":["airway-procedure","dyspnea"],"keywords":"laryngectomy, stoma, Passy-Muir valve, endobronchial tube, neck breather, لارنژکتومی","status":"draft","features":["اینتوباسیون دهانی در لارنژکتومی غیرممکن؛ اینتوباسیون اورژانس با لوله اندوبرونکیال از طریق تراکئوستوما؛ بیش از حد پیش نبر (carina فقط 4 تا 6 cm از استوما)","Passy-Muir valve: دریچه یک‌طرفه روی لوله تراکئوستومی بدون کاف برای صحبت بدون دست؛ بیمار دور لوله بازدم می‌کند: با لوله کافدار مصرف نشود؛ دیسترس تنفسی یا ناتوانی صحبت: ابتدا دریچه را بردار، سپس انسداد لوله را بررسی"],"ddx":[{"n":"Stomal obstruction / mucus plug / stomal stenosis |","cm":1}],"redflags":["دیسترس تنفسی، انسداد استوما"],"guide":"اکسیژن از استوما (نه دهان/بینی)؛ ساکشن؛ در اینتوباسیون: لوله به استومای تراکئا.","section":"eent-oral","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 153: Neck and Upper Airway Disorders, pp. 845–850"}});
